-- Initial Question Bank
INSERT IGNORE INTO questions (course_id, module_num, topic, category, question_type, question_text, code_snippet, options, correct_answer, explanation) VALUES
-- ============================================================================
-- MODULE 1: INTRODUCTION TO ANDROID (27 Questions)
-- ============================================================================
(1, 1, 'Android Overview', 'conceptual', 'multiple_choice', 'Which kernel forms the foundation of the Android Operating System?', NULL, '["Linux", "Windows", "Unix", "MS-DOS"]', 'Linux', 'Android is a mobile operating system based on the Linux kernel.'),
(1, 1, 'Android History', 'conceptual', 'identification', 'In what year did Google purchase Android Inc.?', NULL, NULL, '2005', 'Google purchased Android Inc. in 2005.'),
(1, 1, 'Android Overview', 'conceptual', 'multiple_choice', 'Which of the following is an advantage of the Android platform?', NULL, '["Open Source", "Reduced Development Cost", "Inter App Integration", "All of the above"]', 'All of the above', 'Android features include open-source distribution, reduced development costs, inter-app integration, and a rich development environment.'),
(1, 1, 'Android Versions', 'conceptual', 'identification', 'Which device was the first commercial Android phone to run Android 1.0?', NULL, NULL, 'HTC Dream', 'The first commercial Android version was placed on the HTC Dream device.'),
(1, 1, 'Android Versions', 'conceptual', 'fill_in_blank', 'The official codename given to Android version 1.5 was ___', NULL, NULL, 'Cupcake', 'Android 1.5 Cupcake was the first release with an official dessert codename.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Which feature was introduced in Android 1.6 Donut?', NULL, '["Support for large screen sizes", "Picture-in-Picture", "Dynamic depth photos", "App Bubbles"]', 'Support for large screen sizes', 'Android 1.6 Donut introduced support for large screen sizes, gallery/camera integration, and system speed improvements.'),
(1, 1, 'Android Versions', 'conceptual', 'fill_in_blank', 'Android 2.0 and 2.1 were released under the codename ___', NULL, NULL, 'Eclair', 'Android 2.0 and 2.1 were released under the codename Eclair.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Wi-Fi Hotspot functionality and animated GIF support were introduced in which Android version?', NULL, '["Android 2.2 Froyo", "Android 2.3 Gingerbread", "Android 4.0 ICS", "Android 5.0 Lollipop"]', 'Android 2.2 Froyo', 'Android 2.2 Froyo introduced Wi-Fi Hotspot functionality, animated GIF support, and browser file uploads.'),
(1, 1, 'Android Versions', 'conceptual', 'identification', 'Which Android version was co-developed with Samsung and officially announced on the Nexus S phone?', NULL, NULL, 'Gingerbread', 'Android 2.3 Gingerbread was officially announced on the Nexus S device co-developed with Samsung.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Which Android release was specifically designed for tablets with a 3D UI?', NULL, '["Android 3.0 Honeycomb", "Android 2.2 Froyo", "Android 4.4 KitKat", "Android 7.0 Nougat"]', 'Android 3.0 Honeycomb', 'Android 3.0 Honeycomb was released specifically for tablets with a 3D UI update.'),
(1, 1, 'Android Versions', 'conceptual', 'fill_in_blank', 'Android 4.0 Ice Cream Sandwich synthesized Honeycomb and introduced Face ___', NULL, NULL, 'Lock', 'Android 4.0 Ice Cream Sandwich introduced Face Lock, Wi-Fi Direct, and tabbed browsing.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'What was the primary feature introduced in Android 4.1 Jelly Bean?', NULL, '["Google Now", "Picture in Picture", "Scrolling Screenshots", "Privacy Sandbox"]', 'Google Now', 'Google Now was the main headline feature introduced in Android 4.1 Jelly Bean.'),
(1, 1, 'Android Versions', 'conceptual', 'identification', 'What voice command feature was introduced in Android 4.4 KitKat to trigger Google Now hands-free?', NULL, NULL, 'OK Google', 'Android 4.4 KitKat introduced "OK Google" hands-free voice access.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Which runtime environment was introduced in Android 5.0 Lollipop to replace Dalvik?', NULL, '["ART", "JVM", "DVM", "CLR"]', 'ART', 'Android 5.0 Lollipop introduced ART (Android RunTime) alongside Material Design.'),
(1, 1, 'Android Versions', 'conceptual', 'fill_in_blank', 'Runtime app permission prompts (OPT-in) and fingerprint authentication were added in Android 6.0 ___', NULL, NULL, 'Marshmallow', 'Android 6.0 Marshmallow brought native fingerprint authentication and runtime app permissions.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Native split-screen multi-window mode was introduced in which Android version?', NULL, '["Android 7.0 Nougat", "Android 5.0 Lollipop", "Android 8.0 Oreo", "Android 10"]', 'Android 7.0 Nougat', 'Android 7.0 Nougat introduced native split-screen multi-window mode and Data Saver.'),
(1, 1, 'Android Versions', 'conceptual', 'identification', 'Which feature introduced in Android 8.0 Oreo allows users to view videos in a floating window while using other apps?', NULL, NULL, 'Picture-in-Picture', 'Android 8.0 Oreo introduced Picture-in-Picture (PIP) and adaptive icons.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Adaptive Battery prediction and display cutout (notch) support were introduced in:', NULL, '["Android 9.0 Pie", "Android 10", "Android 11", "Android 12"]', 'Android 9.0 Pie', 'Android 9.0 Pie introduced Adaptive Battery, Adaptive Brightness, and display cutout support.'),
(1, 1, 'Android Versions', 'conceptual', 'fill_in_blank', 'System-wide Dark Theme was officially introduced in Android ___', NULL, NULL, '10', 'Android 10 introduced a system-wide Dark Theme, dynamic depth photo formatting, and location permissions.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Which feature was introduced in Android 11?', NULL, '["Chat Bubbles & Native Screen Recording", "ART Runtime", "Face Lock", "Live Wallpapers"]', 'Chat Bubbles & Native Screen Recording', 'Android 11 introduced conversation bubbles, native screen recording, and auto-revoking permissions.'),
(1, 1, 'Android Versions', 'conceptual', 'identification', 'What internal dessert codename was assigned to Android 12?', NULL, NULL, 'Snow Cone', 'Android 12 was internally codenamed Snow Cone.'),
(1, 1, 'Android Versions', 'conceptual', 'multiple_choice', 'Per-app language preferences and the photo picker were introduced in:', NULL, '["Android 13", "Android 14", "Android 15", "Android 16"]', 'Android 13', 'Android 13 introduced the Photo Picker, native LE Bluetooth support, and per-app language settings.'),
(1, 1, 'Android Architecture', 'conceptual', 'identification', 'What are the 5 layers of the Android Software Architecture stack?', NULL, NULL, 'Applications, Application Framework, Android Runtime, Platform Libraries, Linux Kernel', 'The 5 architecture layers are Applications, Application Framework, Android Runtime, Platform Libraries, and Linux Kernel.'),
(1, 1, 'Android Architecture', 'conceptual', 'multiple_choice', 'Which architecture layer contains the Activity Manager, Package Manager, and Content Providers?', NULL, '["Application Framework", "Linux Kernel", "Platform Libraries", "Android Runtime"]', 'Application Framework', 'The Application Framework layer exposes services like Activity Manager, Package Manager, and Content Providers.'),
(1, 1, 'Android Architecture', 'conceptual', 'fill_in_blank', 'Embedded lightweight database support in the Platform Libraries layer is provided by ___', NULL, NULL, 'SQLite', 'SQLite is included in the Platform Libraries layer for database management.'),
(1, 1, 'Android Architecture', 'conceptual', 'multiple_choice', 'Which core component in the Linux Kernel handles inter-process communication (IPC) in Android?', NULL, '["Binder IPC Driver", "Display Driver", "USB Driver", "Wi-Fi Driver"]', 'Binder IPC Driver', 'The Binder IPC Driver inside the Linux Kernel is responsible for inter-process communication.'),
(1, 1, 'Android Architecture', 'conceptual', 'identification', 'Which virtual machine was historically responsible for executing Android applications before ART?', NULL, NULL, 'Dalvik Virtual Machine', 'The Dalvik Virtual Machine (DVM) was responsible for running mobile applications prior to ART.'),

-- ============================================================================
-- MODULE 2: ANDROID STUDIO (10 Questions)
-- ============================================================================
(1, 2, 'System Requirements', 'conceptual', 'multiple_choice', 'What is the recommended RAM for running Android Studio and the Android Emulator?', NULL, '["8 GB RAM", "2 GB RAM", "1 GB RAM", "512 MB RAM"]', '8 GB RAM', 'Android Studio requires a minimum of 3 GB RAM, but 8 GB RAM is recommended plus 1 GB for the emulator.'),
(1, 2, 'System Requirements', 'conceptual', 'fill_in_blank', 'The minimum screen resolution required to run Android Studio is ___', NULL, NULL, '1280x800', 'The system requirements specify a minimum screen resolution of 1280x800.'),
(1, 2, 'Project Creation', 'conceptual', 'multiple_choice', 'Which default activity template is selected when creating a basic new project in Android Studio?', NULL, '["Empty Views Activity", "No Activity", "C++ Activity", "Automotive Activity"]', 'Empty Views Activity', 'Selecting Empty Views Activity creates a project with a basic layout and activity setup.'),
(1, 2, 'Project Creation', 'conceptual', 'identification', 'What naming convention format is typically used for an Android Package Name during setup?', NULL, NULL, 'com.example.myapp', 'Package names follow reverse domain structure, e.g., com.example.myapplication.'),
(1, 2, 'IDE Interface', 'conceptual', 'multiple_choice', 'Which IDE window section allows you to write and modify layout and source code files?', NULL, '["Editor Window", "Navigation Bar", "Status Bar", "Tool Window Bar"]', 'Editor Window', 'The Editor Window is where you create and edit Kotlin/Java code and XML layouts.'),
(1, 2, 'IDE Interface', 'conceptual', 'fill_in_blank', 'The bar located around the outside of the IDE containing project management buttons is called the Tool ___ Bar.', NULL, NULL, 'Window', 'The Tool Window Bar runs along the outer frame to collapse and expand task panels.'),
(1, 2, 'IDE Interface', 'conceptual', 'identification', 'Which component at the very bottom of Android Studio displays build status and warnings?', NULL, NULL, 'Status Bar', 'The Status Bar displays the status of the project, IDE, and compilation messages.'),
(1, 2, 'Deployment', 'conceptual', 'multiple_choice', 'To run and debug an app on a physical Android device, which setting must be enabled on the phone?', NULL, '["USB Debugging", "Airplane Mode", "NFC Transfer", "Battery Saver"]', 'USB Debugging', 'USB Debugging must be enabled under Developer Options on a physical device.'),
(1, 2, 'Deployment', 'conceptual', 'identification', 'What tool inside Android Studio is used to create and configure Android Virtual Devices (AVDs)?', NULL, NULL, 'Device Manager', 'Device Manager allows developers to select hardware profiles and download system images for emulators.'),
(1, 2, 'Deployment', 'conceptual', 'fill_in_blank', 'Virtual hardware testing instances configured in Android Studio are referred to as ___', NULL, NULL, 'Emulators', 'Applications can be run virtually on built-in Android emulators.'),

-- ============================================================================
-- MODULE 3: INTRODUCTION TO KOTLIN (30 Questions)
-- ============================================================================
(1, 3, 'Kotlin Overview', 'conceptual', 'multiple_choice', 'In what year was Kotlin released by JetBrains?', NULL, '["2016", "2010", "2005", "2020"]', '2016', 'Kotlin was officially released in 2016 by JetBrains.'),
(1, 3, 'Kotlin Syntax', 'conceptual', 'identification', 'Which keyword is used to declare a function in Kotlin?', NULL, NULL, 'fun', 'The fun keyword is used to declare functions in Kotlin.'),
(1, 3, 'Kotlin Syntax', 'technical_fitb', 'multiple_choice', 'What keyword is used to declare an immutable (read-only) variable in Kotlin?', NULL, '["val", "var", "const", "static"]', 'val', 'val is used to declare immutable references, whereas var creates mutable variables.'),
(1, 3, 'Kotlin Syntax', 'technical_fitb', 'fill_in_blank', 'Variables declared with the ___ keyword can be reassigned after initialization.', NULL, NULL, 'var', 'The var keyword creates mutable variables that can be modified after initialization.'),
(1, 3, 'Kotlin Syntax', 'technical_error_detection', 'multiple_choice', 'Identify the compilation error in this Kotlin snippet:', 'val x = 10\nx = 20', '["Reassignment to immutable val", "Missing semicolon", "Invalid type inference", "Syntax error in integer"]', 'Reassignment to immutable val', 'Variables declared with val are immutable and cannot be reassigned.'),
(1, 3, 'Kotlin Null Safety', 'technical_fitb', 'multiple_choice', 'Which modifier promises to initialize a non-null variable at a later point before usage?', NULL, '["lateinit", "nullable", "lazy", "defer"]', 'lateinit', 'lateinit var allows declaring a non-null property that will be initialized later.'),
(1, 3, 'Kotlin Null Safety', 'technical_error_detection', 'multiple_choice', 'What is wrong with the following code snippet?', 'var str: String = "Hello"\nstr = null', '["Cannot assign null to non-null String", "val should be used", "lateinit required", "String must be capitalized"]', 'Cannot assign null to non-null String', 'In Kotlin, types are non-null by default. String? must be used to allow null.'),
(1, 3, 'Kotlin Control Flow', 'technical_fitb', 'multiple_choice', 'What is the output of the following statement?', 'val greeting = if (20 < 18) "Day" else "Night"\nprintln(greeting)', '["Night", "Day", "null", "Compilation Error"]', 'Night', 'Since 20 < 18 is false, the expression evaluates to "Night".'),
(1, 3, 'Kotlin Control Flow', 'conceptual', 'identification', 'Which Kotlin control flow expression serves as a direct replacement for Java switch statements?', NULL, NULL, 'when', 'The when expression replaces traditional switch statements in Kotlin.'),
(1, 3, 'Kotlin Control Flow', 'technical_fitb', 'fill_in_blank', 'In Kotlin ranges, the syntax `for (x in 5..10)` will iterate from 5 to ___ inclusive.', NULL, NULL, '10', 'The range operator `..` includes both the starting and ending values inclusive.'),
(1, 3, 'Kotlin Loops', 'technical_fitb', 'multiple_choice', 'What will this loop output?', 'val nums = arrayOf(1, 5, 10)\nfor (x in nums) { print("$x ") }', '["1 5 10 ", "1..10", "3", "0 1 2 "]', '1 5 10 ', 'The for loop iterates through array elements directly.'),
(1, 3, 'Kotlin OOP', 'conceptual', 'multiple_choice', 'How do you instantiate an object of class `Car` in Kotlin without constructors?', NULL, '["val c1 = Car()", "Car c1 = new Car();", "val c1 = new Car()", "Car c1 = Car.create()"]', 'val c1 = Car()', 'Kotlin does not use the `new` keyword for object instantiation.'),
(1, 3, 'Kotlin OOP', 'conceptual', 'fill_in_blank', 'To allow a class to be inherited in Kotlin, it must be marked with the ___ keyword.', NULL, NULL, 'open', 'Classes in Kotlin are final by default; they must be declared open to allow inheritance.'),
(1, 3, 'Kotlin OOP', 'technical_fitb', 'multiple_choice', 'What block is executed automatically right after primary constructor initialization?', NULL, '["init", "construct", "create", "main"]', 'init', 'Initializer blocks (`init`) run sequentially immediately after primary constructor execution.'),
(1, 3, 'Kotlin OOP', 'technical_fitb', 'fill_in_blank', 'In constructor declarations, default argument values can be set like `class Employee(val id: Int = ___)`', NULL, NULL, '100', 'Primary constructor parameters can specify default parameter values.'),
(1, 3, 'Kotlin OOP', 'conceptual', 'identification', 'What keyword introduces secondary constructors inside a Kotlin class body?', NULL, NULL, 'constructor', 'Secondary constructors are explicitly declared using the `constructor` keyword.'),
(1, 3, 'Kotlin vs Java', 'conceptual', 'multiple_choice', 'How does Kotlin handle static class members found in Java?', NULL, '["Companion Objects", "Static methods", "Global pointers", "Wildcards"]', 'Companion Objects', 'Kotlin does not have static members; companion objects are used instead.'),
(1, 3, 'Kotlin vs Java', 'conceptual', 'fill_in_blank', 'Kotlin completely eliminates checked ___ present in Java.', NULL, NULL, 'exceptions', 'Kotlin removed checked exceptions entirely from its language design.'),
(1, 3, 'Kotlin vs Java', 'conceptual', 'identification', 'What feature in Kotlin automatically casts a variable after a type check (`is`)?', NULL, NULL, 'Smartcast', 'Smartcasts automatically cast variables once verified by `is` checks.'),
(1, 3, 'Kotlin Syntax', 'technical_fitb', 'multiple_choice', 'What will be printed by this string template expression?', 'val age = 20\nprintln("Age is $age")', '["Age is 20", "Age is $age", "Age is age", "Compilation Error"]', 'Age is 20', 'String templates evaluate variable references prefixed with `$`.'),
(1, 3, 'Kotlin Interoperability', 'conceptual', 'multiple_choice', 'What bytecode format do both Java and Kotlin compile down to?', NULL, '["JVM Bytecode", "ARM Machine Code", "DALVIK C++", "LLVM IR"]', 'JVM Bytecode', 'Both Java and Kotlin compile down to JVM bytecode.'),
(1, 3, 'Kotlin Conversion', 'conceptual', 'identification', 'What is the keyboard shortcut in Android Studio to convert a Java file to Kotlin?', NULL, NULL, 'Ctrl+Alt+Shift+K', 'Ctrl+Alt+Shift+K converts an open Java file into a Kotlin file.'),
(1, 3, 'Kotlin Conversion', 'conceptual', 'fill_in_blank', 'When converting Java to Kotlin, the file extension changes from .java to ___', NULL, NULL, '.kt', 'Kotlin source code files use the `.kt` file extension.'),
(1, 3, 'Kotlin Android', 'technical_fitb', 'multiple_choice', 'In Kotlin Android views, how do you set text on a TextView variable `textView`?', NULL, '["textView.text = \\"Hello\\"", "textView.setText(\\"Hello\\");", "textView->text(\\"Hello\\")", "setText(textView, \\"Hello\\")"]', 'textView.text = "Hello"', 'Kotlin allows synthetic property syntax access like `textView.text = "Hello"`.'),
(1, 3, 'Kotlin Fundamentals', 'conceptual', 'multiple_choice', 'Which statement about Kotlin line endings is correct?', NULL, '["Semicolons are optional", "Semicolons are strictly required", "Lines must end with a colon", "Lines must end with a period"]', 'Semicolons are optional', 'In Kotlin, statements do not have to end with a semicolon.'),
(1, 3, 'Kotlin Comments', 'conceptual', 'fill_in_blank', 'Single line comments in Kotlin start with double slashes ___', NULL, NULL, '//', 'Single line comments in Kotlin are written using `//`.'),
(1, 3, 'Kotlin Basics', 'conceptual', 'identification', 'What entry point function is required to execute any standalone Kotlin program?', NULL, NULL, 'main()', 'The `main()` function is the execution entry point of a Kotlin program.'),
(1, 3, 'Kotlin Features', 'conceptual', 'multiple_choice', 'Which feature allows adding new functions to existing classes without modifying their source?', NULL, '["Extension Functions", "Primary Constructors", "Operator Overloading", "Smartcasts"]', 'Extension Functions', 'Extension functions allow extending a class with new functionality without inheritance.'),
(1, 3, 'Kotlin Objects', 'technical_fitb', 'multiple_choice', 'What is the output of this instantiation snippet?', 'class Person(val name: String = "Abe")\nval p = Person()\nprintln(p.name)', '["Abe", "null", "Person", "Compilation Error"]', 'Abe', 'Since no constructor arguments were supplied, the default value "Abe" is assigned.'),
(1, 3, 'Kotlin Conversion', 'conceptual', 'fill_in_blank', 'Pasting Java code directly into a `.kt` file triggers automatic code ___', NULL, NULL, 'conversion', 'Android Studio automatically offers to convert pasted Java code snippets into Kotlin.'),

-- ============================================================================
-- MODULE 4: APPLICATION COMPONENTS AND RESOURCES (18 Questions)
-- ============================================================================
(1, 4, 'Application Components', 'conceptual', 'multiple_choice', 'Which central configuration file links all application components together?', NULL, '["AndroidManifest.xml", "build.gradle", "strings.xml", "R.java"]', 'AndroidManifest.xml', 'The application manifest AndroidManifest.xml describes each component and its interactions.'),
(1, 4, 'Application Components', 'conceptual', 'identification', 'Which core application component presents a single UI screen to the user?', NULL, NULL, 'Activity', 'An activity dictates the user interface and handles user interaction on a single screen.'),
(1, 4, 'Application Components', 'conceptual', 'multiple_choice', 'Which component handles background processing without providing a user interface?', NULL, '["Service", "Activity", "Content Provider", "View"]', 'Service', 'A Service runs in the background to perform long-running operations like playing music.'),
(1, 4, 'Application Components', 'conceptual', 'fill_in_blank', 'Inter-application broadcast messages from the system are intercepted by Broadcast ___', NULL, NULL, 'Receivers', 'Broadcast Receivers intercept and respond to system-wide or app-initiated broadcast notifications.'),
(1, 4, 'Application Components', 'conceptual', 'identification', 'Which application component manages shared app data and database access requests?', NULL, NULL, 'Content Provider', 'Content Providers supply data from one application to others upon request.'),
(1, 4, 'Application Components', 'conceptual', 'multiple_choice', 'Asynchronous messaging objects used to request actions from other components are called:', NULL, '["Intents", "Layouts", "Views", "Fragments"]', 'Intents', 'Intents are message objects that wire application components together.'),
(1, 4, 'Application Components', 'conceptual', 'fill_in_blank', 'Reusable portions of user interface nested inside an Activity are called ___', NULL, NULL, 'Fragments', 'Fragments represent a modular portion of a user interface inside an activity.'),
(1, 4, 'Resources Organization', 'conceptual', 'multiple_choice', 'In which directory under `res/` are vector shapes, bitmaps, and layer lists stored?', NULL, '["res/drawable/", "res/layout/", "res/values/", "res/mipmap/"]', 'res/drawable/', 'Bitmap files (.png, .jpg) and XML shape drawables reside inside `res/drawable/`.'),
(1, 4, 'Resources Organization', 'conceptual', 'identification', 'Which `res/` directory holds XML files defining screen user interface layouts?', NULL, NULL, 'res/layout/', 'Layout definitions for user interfaces are stored in `res/layout/`.'),
(1, 4, 'Resources Organization', 'conceptual', 'multiple_choice', 'Where are simple value XML files like `strings.xml`, `colors.xml`, and `styles.xml` stored?', NULL, '["res/values/", "res/raw/", "res/xml/", "res/font/"]', 'res/values/', 'The `res/values/` subfolder holds XML files containing strings, integers, colors, and styles.'),
(1, 4, 'Resources Organization', 'conceptual', 'fill_in_blank', 'Arbitrary raw files saved in their uncompiled form belong inside the res/___/ directory.', NULL, NULL, 'raw', 'Arbitrary assets accessed via raw stream resource IDs are saved under `res/raw/`.'),
(1, 4, 'Resources Organization', 'conceptual', 'identification', 'Which resource folder contains app launcher icons targeted for different screen densities?', NULL, NULL, 'res/mipmap/', 'Mipmap directories (`res/mipmap/`) hold launcher icons across resolutions.'),
(1, 4, 'Resources Access', 'conceptual', 'multiple_choice', 'What auto-generated class contains integer resource IDs for accessing resources in code?', NULL, '["R class", "BuildConfig", "Manifest class", "System class"]', 'R class', 'When compiled, an `R` class is generated containing static integer IDs for all assets in `res/`.'),
(1, 4, 'Resources Access', 'technical_fitb', 'multiple_choice', 'How do you programmatically reference a string resource named `hello` in Kotlin?', NULL, '["R.string.hello", "@string/hello", "res.strings.hello", "String.get(hello)"]', 'R.string.hello', 'Resources are accessed in code via `R.subdirectory.filename` notation.'),
(1, 4, 'Resources Access', 'technical_fitb', 'fill_in_blank', 'To reference a color resource named `primary` inside an XML layout, use the syntax `@color/___`', NULL, NULL, 'primary', 'XML layout references use the `@type/res_name` prefix.'),
(1, 4, 'Resources Access', 'technical_fitb', 'multiple_choice', 'Which code snippet loads an XML layout file `activity_main.xml` inside an Activity `onCreate` callback?', NULL, '["setContentView(R.layout.activity_main);", "inflate(R.id.activity_main);", "setLayout(activity_main);", "R.layout.activity_main.load();"]', 'setContentView(R.layout.activity_main);', '`setContentView()` inflates the visual layout resource onto the activity screen.'),
(1, 4, 'Resources Access', 'technical_fitb', 'fill_in_blank', 'To set an image view programmatically to `myimage.png`, call `imageView.setImageResource(R.drawable.___ )`', NULL, NULL, 'myimage', '`setImageResource()` accepts a drawable resource ID generated in `R.drawable`.'),
(1, 4, 'Resources Organization', 'conceptual', 'identification', 'Which `res/` subfolder contains XML property animation files accessed via `R.animator`?', NULL, NULL, 'res/animator/', 'Property animations are stored in `res/animator/` and accessed via `R.animator`.'),

-- ============================================================================
-- MODULE 5: ACTIVITIES (15 Questions)
-- ============================================================================
(1, 5, 'Activity Basics', 'conceptual', 'multiple_choice', 'In desktop applications, an Android Activity is equivalent to a:', NULL, '["Window", "Database", "File Stream", "Process Thread"]', 'Window', 'An Activity represents one visual screen, very similar to a desktop window.'),
(1, 5, 'Activity Creation', 'conceptual', 'fill_in_blank', 'All Android activity classes must inherit directly or indirectly from android.app.___', NULL, NULL, 'Activity', 'Every activity class is a subclass of `android.app.Activity` or `AppCompatActivity`.'),
(1, 5, 'Activity Manifest', 'conceptual', 'identification', 'Which XML tag inside `AndroidManifest.xml` registers an Activity component?', NULL, NULL, '<activity>', 'Activities must be declared as child `<activity>` elements under `<application>`.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'multiple_choice', 'Which callback is the very first method invoked when an Activity is created?', NULL, '["onCreate()", "onStart()", "onResume()", "onRestart()"]', 'onCreate()', '`onCreate()` is the first callback fired when an activity is launched.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'fill_in_blank', 'The callback invoked when an activity becomes visually visible to the user is ___', NULL, NULL, 'onStart()', '`onStart()` is called when the activity becomes visible.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'multiple_choice', 'When an activity enters the foreground and starts receiving user input, which method is called?', NULL, '["onResume()", "onStart()", "onPause()", "onCreate()"]', 'onResume()', '`onResume()` is invoked when the activity enters the running foreground state.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'identification', 'Which lifecycle callback is invoked when an activity is partially hidden or losing user focus?', NULL, NULL, 'onPause()', '`onPause()` fires when another activity comes into the foreground, partially obscuring the screen.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'multiple_choice', 'Which method is called when an activity is no longer visible on screen?', NULL, '["onStop()", "onPause()", "onDestroy()", "onRestart()"]', 'onStop()', '`onStop()` is called when the activity is completely hidden from view.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'fill_in_blank', 'Before an activity is completely removed from memory, the system calls on___()', NULL, NULL, 'Destroy', '`onDestroy()` is the final callback received before system destruction.'),
(1, 5, 'Activity Lifecycle', 'conceptual', 'identification', 'Which lifecycle callback executes when a stopped activity is navigated back to by the user?', NULL, NULL, 'onRestart()', '`onRestart()` fires when an activity restarts after being stopped.'),
(1, 5, 'Activity Lifecycle', 'technical_fitb', 'multiple_choice', 'What is the correct execution order of callbacks during normal activity startup?', NULL, '["onCreate() -> onStart() -> onResume()", "onStart() -> onCreate() -> onResume()", "onResume() -> onStart() -> onCreate()", "onCreate() -> onResume() -> onStart()"]', 'onCreate() -> onStart() -> onResume()', 'The startup lifecycle sequence is `onCreate()`, followed by `onStart()`, then `onResume()`.'),
(1, 5, 'Activity Creation', 'technical_fitb', 'fill_in_blank', 'In Kotlin activity creation, views are inflated inside `onCreate()` using `setContentView(R.layout.___)`', NULL, NULL, 'activity_main', '`setContentView(R.layout.activity_main)` loads the associated XML design file.'),
(1, 5, 'Activity Execution', 'conceptual', 'multiple_choice', 'What happens if Android system memory is critically low while an activity is stopped or paused?', NULL, '["The OS kills the process", "The app freezes permanently", "It auto-reboots the device", "It skips to onDestroy()"]', 'The OS kills the process', 'When high-priority apps require memory, the OS kills background processes in `onPause()` or `onStop()`.'),
(1, 5, 'Activity Basics', 'conceptual', 'identification', 'Which activity is launched automatically when a user opens the application icon?', NULL, NULL, 'Main Activity', 'The app starts by showing the designated main activity.'),
(1, 5, 'Activity Lifecycle', 'technical_fitb', 'multiple_choice', 'In Java/Kotlin, what method call must be executed first inside overridden lifecycle methods like `onCreate()`?', NULL, '["super.onCreate(savedInstanceState)", "this.onCreate()", "initLifecycle()", "Activity.start()"]', 'super.onCreate(savedInstanceState)', 'Overridden lifecycle methods must invoke their superclass implementation first.');



-- ============================================================================
-- QUESTION BATCH #1 (120 Questions)
-- ============================================================================
INSERT IGNORE INTO questions (course_id, module_num, topic, category, question_type, question_text, code_snippet, options, correct_answer, explanation) VALUES
(2, 1, 'Types of Analytics', 'conceptual', 'multiple_choice', 'A retail company has already summarized monthly sales by region. Management now wants to understand why one region consistently underperforms despite similar marketing expenditures. Which type of analytics should be performed next?', NULL, '["Descriptive Analytics","Diagnostic Analytics","Predictive Analytics","Prescriptive Analytics"]', 'Diagnostic Analytics', 'Descriptive analytics summarizes what happened, while diagnostic analytics investigates the underlying causes of observed outcomes.'),
(2, 1, 'Data Value Chain', 'conceptual', 'multiple_choice', 'A company collects millions of transaction records every day but executives complain they cannot make informed decisions because reports are inconsistent and delayed. Which stage of the Data Value Chain is MOST likely insufficient?', NULL, '["Data Collection","Analytics","Decision","Application"]', 'Analytics', 'Although data is available, the inability to transform it into reliable insights indicates weaknesses in the analytics stage of the data value chain.'),
(2, 1, 'Data Sources', 'conceptual', 'multiple_choice', 'A telecommunications company wants to predict customer churn. Which additional data source would MOST likely enrich existing customer account records by providing customer opinions, preferences, and satisfaction information unavailable in transactional databases?', NULL, '["Surveys","Duplicate transaction logs","Database backups","Archived invoices"]', 'Surveys', 'Survey data can provide behavioral and satisfaction information that is typically unavailable in structured transactional records.'),
(2, 1, 'Types of Analytics', 'conceptual', 'fill_in_blank', 'An analytics approach that recommends the best course of action after evaluating different scenarios is called ________ analytics.', NULL, NULL, 'Prescriptive', 'Prescriptive analytics recommends actions by evaluating possible alternatives and their outcomes.'),
(2, 1, 'Data Quality', 'conceptual', 'multiple_choice', 'An analyst discovers duplicate customer IDs, inconsistent product names, and missing order dates before computing summary statistics. What is the PRIMARY reason these issues should be resolved first?', NULL, '["To reduce storage requirements","To improve visualization colors","To ensure analytical conclusions are reliable","To increase database size"]', 'To ensure analytical conclusions are reliable', 'Poor data quality directly affects the validity of descriptive statistics and subsequent analytical decisions.'),
(2, 1, 'Data Value Chain', 'conceptual', 'identification', 'A company successfully generates accurate dashboards but managers consistently ignore the insights and continue relying on intuition. Which stage of the Data Value Chain is failing?', NULL, NULL, 'Decision', 'The analytics stage produced useful insights, but organizational decision-making failed to utilize them.'),
(2, 1, 'Descriptive Analytics', 'conceptual', 'multiple_choice', 'A dataset contains several unusually high salary values caused by executive compensation. Which descriptive measure would BEST represent the typical employee salary?', NULL, '["Mean","Median","Maximum","Range"]', 'Median', 'The median is resistant to extreme values and better represents the center of skewed distributions.'),
(2, 1, 'Types of Analytics', 'conceptual', 'multiple_choice', 'Which sequence correctly represents the progression of analytics maturity discussed in the course?', NULL, '["Predictive → Diagnostic → Descriptive → Prescriptive","Descriptive → Diagnostic → Predictive → Prescriptive","Diagnostic → Descriptive → Predictive → Prescriptive","Descriptive → Predictive → Diagnostic → Prescriptive"]', 'Descriptive → Diagnostic → Predictive → Prescriptive', 'The analytics maturity model progresses from describing events to explaining them, predicting future outcomes, and finally recommending actions.'),
(2, 1, 'EDA', 'conceptual', 'multiple_choice', 'Two analysts examine the same sales dataset. Analyst A immediately builds a predictive model, while Analyst B first profiles missing values, checks variable distributions, and investigates outliers. Which approach is more consistent with the principles of Exploratory Data Analysis?', NULL, '["Analyst A because predictive models automatically detect data issues","Analyst B because understanding data quality should precede modeling","Both approaches are equally appropriate","Neither approach because EDA occurs after prediction"]', 'Analyst B because understanding data quality should precede modeling', 'EDA emphasizes understanding data characteristics and quality before performing advanced analyses or modeling.'),
(2, 1, 'Data Sources', 'conceptual', 'multiple_choice', 'A financial institution wants to enhance its customer database by purchasing demographic information from another company. According to the course material, this external source is best classified as:', NULL, '["Transactional Data","Survey Data","Data Pooler","Unstructured Data"]', 'Data Pooler', 'Data poolers collect and sell data that organizations can use to enrich their existing datasets.'),
(2, 1, 'Data Profiling', 'conceptual', 'multiple_choice', 'An analyst finds that 18% of records have missing values in the "Customer Age" column before beginning an exploratory analysis. Which action would MOST strengthen the credibility of any conclusions drawn from the dataset?', NULL, '["Proceed with visualization immediately","Document and investigate the missing values before analysis","Replace all missing values with zero","Delete the entire dataset"]', 'Document and investigate the missing values before analysis', 'Data profiling is intended to identify quality issues before analysis. Understanding why data is missing leads to more reliable analytical conclusions.'),
(2, 1, 'Descriptive Measures', 'conceptual', 'multiple_choice', 'A sales manager wants to compare the performance of two branches. Branch A has consistently average sales, while Branch B has the same average but much larger fluctuations. Which descriptive measure would BEST distinguish these branches?', NULL, '["Mean","Median","Standard Deviation","Minimum"]', 'Standard Deviation', 'Standard deviation measures variability. Two datasets may have identical means but different levels of consistency.'),
(2, 1, 'Data Sources', 'conceptual', 'identification', 'Data collected directly from purchases, payments, or customer transactions are collectively known as __________ data.', NULL, NULL, 'Transactional', 'Transactional data captures structured information generated through business transactions.'),
(2, 1, 'Exploratory Data Analysis', 'conceptual', 'multiple_choice', 'A supermarket discovers unusually high sales on one day during EDA. Before removing the observation as an outlier, what should the analyst do FIRST?', NULL, '["Delete the observation immediately","Verify whether the value reflects a legitimate business event","Replace it with the average","Ignore the observation during analysis"]', 'Verify whether the value reflects a legitimate business event', 'Not every outlier is an error. Some represent genuine events such as holiday promotions or product launches.'),
(2, 1, 'Data Value Chain', 'conceptual', 'multiple_choice', 'A hospital has successfully transformed raw patient records into dashboards showing treatment outcomes. However, patient care protocols remain unchanged despite repeated evidence from the dashboards. Which statement BEST explains the situation?', NULL, '["The descriptive analytics stage failed","The organization failed to convert insights into decisions","The database contains insufficient records","The dashboards should have used predictive analytics instead"]', 'The organization failed to convert insights into decisions', 'The value of analytics is realized only when insights lead to informed actions and decisions.'),
(2, 1, 'Types of Analytics', 'conceptual', 'fill_in_blank', 'Analytics that primarily answers the question "Why did it happen?" is called __________ analytics.', NULL, NULL, 'Diagnostic', 'Diagnostic analytics investigates the causes behind observed events or trends.'),
(2, 1, 'Descriptive Measures', 'conceptual', 'multiple_choice', 'A dataset contains monthly sales figures with several missing values. An analyst computes the average without investigating the missing entries and reports the result to management. Which is the GREATEST risk of this approach?', NULL, '["The calculation will always be mathematically incorrect","The reported average may misrepresent the true business performance","The median automatically becomes invalid","The dataset can no longer be visualized"]', 'The reported average may misrepresent the true business performance', 'Ignoring missing data may bias descriptive statistics and produce misleading business insights.'),
(2, 1, 'Data Types', 'conceptual', 'multiple_choice', 'A company wants to analyze customer feedback collected from social media posts alongside structured sales records. Why is integrating these two data sources valuable?', NULL, '["Because unstructured data replaces structured data","Because combining structured and unstructured data can reveal insights unavailable from either source alone","Because social media data is always more accurate","Because structured data becomes unnecessary"]', 'Because combining structured and unstructured data can reveal insights unavailable from either source alone', 'Structured and unstructured data complement one another by providing both measurable transactions and qualitative customer sentiment.'),
(2, 1, 'Descriptive Analytics', 'conceptual', 'multiple_choice', 'A manager concludes that because product sales increased after a marketing campaign, the campaign alone caused the increase. Based only on descriptive analytics, what is the strongest criticism of this conclusion?', NULL, '["Descriptive analytics alone cannot establish causation","Descriptive analytics always predicts future outcomes","The manager should compute another average","Descriptive analytics requires machine learning"]', 'Descriptive analytics alone cannot establish causation', 'Descriptive analytics summarizes observations but cannot determine causal relationships without further investigation.'),
(2, 1, 'Data Profiling', 'conceptual', 'multiple_choice', 'During EDA, an analyst discovers duplicate customer records. If left unresolved, which analytical outcome is MOST likely to be affected?', NULL, '["The color of charts","Summary statistics such as counts and averages","The database schema","The file format"]', 'Summary statistics such as counts and averages', 'Duplicate records inflate counts and can distort averages, percentages, and other descriptive statistics.'),
(2, 1, 'Descriptive Measures', 'conceptual', 'multiple_choice', 'A business analyst is comparing customer spending across two regions. Region A has a higher average purchase amount, but Region B has a much larger median purchase amount. What is the MOST reasonable conclusion?', NULL, '["Region A definitely has higher customer spending","Region B has no outliers","Additional investigation of the distributions is needed before making conclusions","The average is always more reliable than the median"]', 'Additional investigation of the distributions is needed before making conclusions', 'Differences between the mean and median may indicate skewness or outliers. Examining the distributions provides better insight before making business decisions.'),
(2, 1, 'Pivot Tables', 'conceptual', 'multiple_choice', 'A regional manager wants to compare quarterly revenue by product category across multiple branches while allowing managers to interactively filter results. Which Excel feature is MOST appropriate for this task?', NULL, '["Conditional Formatting","Pivot Table","Goal Seek","COUNTIFS"]', 'Pivot Table', 'Pivot Tables efficiently summarize large datasets while allowing users to dynamically filter, group, and compare information.'),
(2, 1, 'Descriptive Measures', 'conceptual', 'identification', 'Which descriptive measure divides an ordered dataset into four equal parts?', NULL, NULL, 'Quartile', 'Quartiles partition an ordered dataset into four equal sections and are commonly used to understand data distribution.'),
(2, 1, 'Exploratory Data Analysis', 'conceptual', 'multiple_choice', 'After profiling a dataset, an analyst notices that customer ages range from 18 to 65 except for one record with an age of 320. What is the BEST next step?', NULL, '["Replace it immediately with the mean age","Verify whether it is a data entry error before deciding how to handle it","Ignore the value because averages are unaffected","Delete every record above age 65"]', 'Verify whether it is a data entry error before deciding how to handle it', 'EDA focuses on understanding unusual observations before modifying or removing them.'),
(2, 1, 'Data Value Chain', 'conceptual', 'multiple_choice', 'An organization regularly generates accurate analytical reports, but department heads make conflicting decisions because each interprets the reports differently. Which improvement would MOST strengthen the final stage of the Data Value Chain?', NULL, '["Collect more raw data","Improve communication and standardize decision guidelines","Store data in multiple databases","Reduce the number of reports generated"]', 'Improve communication and standardize decision guidelines', 'The value chain concludes with informed decision-making. Consistent interpretation of insights improves organizational outcomes.'),
(2, 1, 'Descriptive Measures', 'conceptual', 'fill_in_blank', 'The Excel function commonly used to determine the middle value of an ordered dataset is __________.', NULL, NULL, 'MEDIAN', 'The MEDIAN function returns the middle observation after the data has been ordered.'),
(2, 1, 'Data Quality', 'conceptual', 'multiple_choice', 'A data scientist notices that product names appear as "Laptop", "Laptop ", and "laptop" in different records. If left unresolved, which activity is MOST likely to produce misleading results?', NULL, '["Grouping and aggregation","Saving the workbook","Printing the report","Changing the worksheet name"]', 'Grouping and aggregation', 'Inconsistent text values create separate categories during grouping, leading to inaccurate summaries and analyses.'),
(2, 1, 'Data Sources', 'conceptual', 'multiple_choice', 'A marketing team combines online purchase history with customer comments collected from social media. What is the PRIMARY advantage of using both structured and unstructured data?', NULL, '["It guarantees accurate predictions","It provides both quantitative behavior and qualitative context","It eliminates the need for data cleaning","It automatically identifies causal relationships"]', 'It provides both quantitative behavior and qualitative context', 'Structured data explains what customers did, while unstructured data often explains opinions or motivations behind those actions.'),
(2, 1, 'Descriptive Analytics', 'conceptual', 'multiple_choice', 'A company''s dashboard shows that monthly sales have steadily increased over the past year. Which additional analysis would BEST support a manager who wants to understand the reason behind the increase?', NULL, '["Compute another total sales value","Perform diagnostic analytics to investigate contributing factors","Collect fewer observations","Generate another dashboard using different colors"]', 'Perform diagnostic analytics to investigate contributing factors', 'Descriptive analytics identifies trends, while diagnostic analytics investigates the causes of those trends.'),
(2, 1, 'Data Profiling', 'conceptual', 'multiple_choice', 'An analyst profiles a customer database before creating visualizations and discovers that several important fields contain inconsistent formats. Why is resolving these issues BEFORE visualization considered good analytical practice?', NULL, '["Charts cannot display formatted data","Visualizations based on inconsistent data may lead to incorrect interpretations","Visualization software cannot process text fields","Formatting errors automatically invalidate the database"]', 'Visualizations based on inconsistent data may lead to incorrect interpretations', 'Data profiling improves the accuracy and trustworthiness of visualizations by ensuring the underlying data is consistent and reliable.'),

(2, 2, 'Diagnostic Analytics', 'conceptual', 'multiple_choice', 'A university notices that the passing rate in a programming course has declined over the past three semesters. Which analytical approach should be used to determine the factors contributing to the decline?', NULL, '["Descriptive Analytics","Diagnostic Analytics","Predictive Analytics","Prescriptive Analytics"]', 'Diagnostic Analytics', 'Diagnostic analytics focuses on identifying the underlying reasons behind observed outcomes by investigating relationships and contributing factors.'),
(2, 2, 'Functions of Diagnostic Analytics', 'conceptual', 'multiple_choice', 'A company observes an unexpected increase in customer complaints. Which activity BEST represents the "drill into analytics" function of diagnostic analytics?', NULL, '["Forecasting future complaints","Examining complaints by branch, product, and employee to locate the source of the increase","Calculating the monthly average complaints","Recommending a new customer service policy"]', 'Examining complaints by branch, product, and employee to locate the source of the increase', 'Drill-down analysis investigates data at finer levels of detail to discover the underlying source of an issue.'),
(2, 2, 'Association vs. Correlation', 'conceptual', 'identification', 'The statistical measure used to quantify the strength and direction of a linear relationship between two variables is called the __________.', NULL, NULL, 'Correlation Coefficient', 'The correlation coefficient measures the strength and direction of a linear relationship between two quantitative variables.'),
(2, 2, 'Association vs. Correlation', 'conceptual', 'multiple_choice', 'A researcher observes that students who attend more review sessions generally obtain higher examination scores. Which concept BEST describes this observation if the relationship is specifically linear?', NULL, '["Association","Correlation","Variance","Regression"]', 'Correlation', 'Correlation specifically refers to the strength and direction of a linear relationship, whereas association refers to a more general relationship.'),
(2, 2, 'Correlation Coefficient', 'conceptual', 'multiple_choice', 'An analyst computes a correlation coefficient of -0.91 between daily exercise time and resting heart rate. Which interpretation is MOST appropriate?', NULL, '["There is a strong positive relationship.","There is a weak negative relationship.","There is a strong negative linear relationship.","The variables are unrelated."]', 'There is a strong negative linear relationship.', 'A correlation coefficient close to -1 indicates a strong negative linear relationship.'),
(2, 2, 'Hypothesis Testing', 'conceptual', 'fill_in_blank', 'The statement that assumes no significant difference or relationship exists is called the __________ hypothesis.', NULL, NULL, 'Null', 'The null hypothesis (H₀) represents the default assumption tested during hypothesis testing.'),
(2, 2, 'Hypothesis Testing', 'conceptual', 'multiple_choice', 'A data analyst wants to determine whether customer satisfaction differs between two independent branches of a company. Which statistical test is MOST appropriate?', NULL, '["Chi-Square Test","Independent Samples T-Test","One-Way ANOVA","Correlation Analysis"]', 'Independent Samples T-Test', 'An independent samples t-test compares the means of two independent groups.'),
(2, 2, 'Chi-Square Test', 'conceptual', 'multiple_choice', 'A researcher wants to determine whether customers'' preferred payment method is related to age group. Which statistical test should be selected?', NULL, '["Independent Samples T-Test","Chi-Square Test of Independence","One-Way ANOVA","Pearson Correlation"]', 'Chi-Square Test of Independence', 'The Chi-Square Test of Independence determines whether two categorical variables are associated.'),
(2, 2, 'One-Way ANOVA', 'conceptual', 'multiple_choice', 'A manager wants to compare the average monthly sales among four different branches. Which statistical test is MOST appropriate?', NULL, '["Independent Samples T-Test","Pearson Correlation","One-Way ANOVA","Chi-Square Test"]', 'One-Way ANOVA', 'One-Way ANOVA compares the means of three or more independent groups.'),
(2, 2, 'Diagnostic Analytics', 'conceptual', 'multiple_choice', 'A business analyst concludes that two variables are highly correlated and immediately claims that one variable causes the other. Why is this conclusion inappropriate?', NULL, '["Correlation only measures association and does not establish causation.","Correlation coefficients cannot be negative.","Diagnostic analytics only applies to financial data.","Correlation is only valid for categorical variables."]', 'Correlation only measures association and does not establish causation.', 'A strong correlation indicates a relationship between variables but does not prove that one variable causes changes in the other.'),
(2, 2, 'Hypothesis Testing', 'conceptual', 'multiple_choice', 'A researcher is preparing to conduct a hypothesis test. Which hypothesis represents the default assumption of no significant difference or relationship in a hypothesis test?', NULL, '["Alternative Hypothesis","Null Hypothesis","Research Conclusion","Decision Rule"]', 'Null Hypothesis', 'The null hypothesis serves as the default assumption that is evaluated using sample evidence.'),
(2, 2, 'Association vs. Correlation', 'conceptual', 'multiple_choice', 'Two variables consistently increase together, but the relationship does not follow a straight line. Which statement is MOST accurate?', NULL, '["The variables are positively correlated.","The variables are associated, but a strong linear correlation may not exist.","The variables are independent.","The variables have a negative correlation."]', 'The variables are associated, but a strong linear correlation may not exist.', 'Association refers to a general relationship, while correlation specifically measures a linear relationship.'),
(2, 2, 'Correlation Coefficient', 'conceptual', 'identification', 'What value of the correlation coefficient indicates no linear relationship between two variables?', NULL, NULL, '0', 'A correlation coefficient of zero indicates the absence of a linear relationship, although other types of relationships may still exist.'),
(2, 2, 'Chi-Square Test', 'conceptual', 'multiple_choice', 'A hospital wants to determine whether blood type is related to patient recovery status. Which characteristic of the variables makes the Chi-Square Test appropriate?', NULL, '["Both variables are numerical.","Both variables are categorical.","One variable is continuous and one is categorical.","Both variables represent time measurements."]', 'Both variables are categorical.', 'The Chi-Square Test of Independence evaluates whether two categorical variables are associated.'),
(2, 2, 'T-Test', 'conceptual', 'multiple_choice', 'An HR manager compares the average productivity scores of employees before and after a training program using the same group of employees. Which statistical test is MOST appropriate?', NULL, '["Independent Samples T-Test","Paired Samples T-Test","One-Way ANOVA","Chi-Square Test"]', 'Paired Samples T-Test', 'A paired samples t-test compares two related measurements taken from the same subjects.'),
(2, 2, 'One-Way ANOVA', 'conceptual', 'fill_in_blank', 'One-Way __________ is the statistical procedure commonly used to compare the means of three or more independent groups.', NULL, NULL, 'ANOVA', 'One-Way ANOVA determines whether significant differences exist among the means of three or more groups.'),
(2, 2, 'Diagnostic Analytics', 'conceptual', 'multiple_choice', 'A manufacturing company discovers that product defects increased during the last quarter. Which question BEST represents the objective of diagnostic analytics?', NULL, '["How many defective products were produced?","Why did the number of defective products increase?","How many defects will occur next quarter?","Which solution should be implemented immediately?"]', 'Why did the number of defective products increase?', 'Diagnostic analytics focuses on identifying the causes behind observed outcomes.'),
(2, 2, 'Correlation Coefficient', 'conceptual', 'multiple_choice', 'A correlation coefficient of 0.88 is computed between advertising expenditure and sales revenue. Which interpretation is MOST appropriate?', NULL, '["A strong positive linear relationship exists.","A weak positive relationship exists.","A strong negative relationship exists.","No relationship exists between the variables."]', 'A strong positive linear relationship exists.', 'Correlation coefficients close to +1 indicate a strong positive linear relationship.'),
(2, 2, 'Hypothesis Testing', 'conceptual', 'multiple_choice', 'Which outcome of hypothesis testing indicates that the sample provides sufficient evidence against the null hypothesis?', NULL, '["Accept the null hypothesis.","Reject the null hypothesis.","Increase the sample size automatically.","Repeat the experiment without analysis."]', 'Reject the null hypothesis.', 'When statistical evidence is sufficient, the null hypothesis is rejected in favor of the alternative hypothesis.'),
(2, 2, 'Functions of Diagnostic Analytics', 'conceptual', 'multiple_choice', 'According to the module, which of the following is NOT a primary function of diagnostic analytics?', NULL, '["Identify anomalies","Drill into analytics","Determine causal relationships","Recommend the optimal decision"]', 'Recommend the optimal decision', 'Recommending the best course of action belongs to prescriptive analytics, not diagnostic analytics.'),
(2, 2, 'Association vs. Correlation', 'conceptual', 'multiple_choice', 'A researcher observes that as the number of study hours increases, examination scores also tend to increase. Which statement BEST describes this observation?', NULL, '["The variables exhibit a positive correlation.","The variables exhibit a negative correlation.","The variables are independent.","The variables have no association."]', 'The variables exhibit a positive correlation.', 'A positive correlation indicates that both variables tend to increase together.'),
(2, 2, 'Hypothesis Testing', 'conceptual', 'identification', 'The hypothesis that represents the research claim or expected difference is called the __________ hypothesis.', NULL, NULL, 'Alternative', 'The alternative hypothesis (H₁ or Hₐ) represents the claim that there is a significant difference or relationship.'),
(2, 2, 'Diagnostic Analytics', 'conceptual', 'multiple_choice', 'A company notices that customer retention has declined significantly. Which activity should be performed FIRST according to the principles of diagnostic analytics?', NULL, '["Recommend a new retention strategy","Investigate possible factors contributing to the decline","Predict next year''s retention rate","Implement a marketing campaign immediately"]', 'Investigate possible factors contributing to the decline', 'Diagnostic analytics focuses on understanding the reasons behind observed outcomes before making recommendations.'),
(2, 2, 'Chi-Square Test', 'conceptual', 'multiple_choice', 'A university wants to determine whether students'' preferred learning modality (Online, Hybrid, Face-to-Face) is associated with their year level. Which statistical test is MOST appropriate?', NULL, '["Pearson Correlation","Independent Samples T-Test","Chi-Square Test of Independence","One-Way ANOVA"]', 'Chi-Square Test of Independence', 'The Chi-Square Test of Independence is appropriate when determining whether two categorical variables are associated.'),
(2, 2, 'Correlation Coefficient', 'conceptual', 'multiple_choice', 'Which correlation coefficient indicates the strongest positive linear relationship?', NULL, '["0.15","0.52","0.81","-0.81"]', '0.81', 'Correlation coefficients closer to +1 represent stronger positive linear relationships.'),
(2, 2, 'One-Way ANOVA', 'conceptual', 'multiple_choice', 'A food delivery company wants to compare the average delivery times of five different branches. Which statistical test should be selected?', NULL, '["Chi-Square Test","Paired Samples T-Test","One-Way ANOVA","Pearson Correlation"]', 'One-Way ANOVA', 'One-Way ANOVA compares the means of three or more independent groups.'),
(2, 2, 'Functions of Diagnostic Analytics', 'conceptual', 'fill_in_blank', 'One important function of diagnostic analytics is to identify __________, or unusual patterns that differ from normal observations.', NULL, NULL, 'Anomalies', 'Diagnostic analytics identifies anomalies that may require further investigation.'),
(2, 2, 'T-Test', 'conceptual', 'multiple_choice', 'A pharmaceutical company compares the average recovery time of patients receiving Drug A and Drug B using two different groups of patients. Which statistical test is MOST appropriate?', NULL, '["Independent Samples T-Test","Paired Samples T-Test","Chi-Square Test","One-Way ANOVA"]', 'Independent Samples T-Test', 'An independent samples t-test compares the means of two independent groups.'),
(2, 2, 'Association vs. Correlation', 'conceptual', 'multiple_choice', 'Which statement correctly differentiates association from correlation?', NULL, '["Association only applies to numerical variables.","Correlation is a specific measure of a linear relationship, while association refers to a broader relationship.","Association and correlation always have identical meanings.","Correlation can only be used for categorical variables."]', 'Correlation is a specific measure of a linear relationship, while association refers to a broader relationship.', 'The module distinguishes association as a general relationship and correlation as a measure of linear association.'),
(2, 2, 'Hypothesis Testing', 'conceptual', 'multiple_choice', 'A researcher compares three teaching methods to determine whether average student performance differs among them. Which statistical procedure is MOST appropriate?', NULL, '["Chi-Square Test","Independent Samples T-Test","One-Way ANOVA","Pearson Correlation"]', 'One-Way ANOVA', 'One-Way ANOVA is used to compare the means of three or more independent groups.'),

(2, 3, 'Predictive Analytics', 'conceptual', 'multiple_choice', 'A retail company wants to estimate next month''s sales based on historical sales data and advertising expenditures. Which branch of analytics is primarily being applied?', NULL, '["Descriptive Analytics","Diagnostic Analytics","Predictive Analytics","Prescriptive Analytics"]', 'Predictive Analytics', 'Predictive analytics uses historical data to forecast future outcomes.'),
(2, 3, 'Predictive Analytics Process', 'conceptual', 'multiple_choice', 'Before building a regression model, a data science team meets with stakeholders to define the business objective, success criteria, and deployment requirements. Which stage of the predictive analytics process does this represent?', NULL, '["Data Sampling","Project Design","Model Validation","Data Exploration"]', 'Project Design', 'Project Design establishes the objectives, requirements, and success criteria before any modeling begins.'),
(2, 3, 'Linear Regression', 'conceptual', 'identification', 'In a linear regression model, the variable being predicted is called the __________ variable.', NULL, NULL, 'Dependent', 'The dependent variable (Y) is the outcome that the regression model aims to predict.'),
(2, 3, 'Linear Regression', 'conceptual', 'multiple_choice', 'Which component of the linear regression equation represents the baseline value of the dependent variable when all predictor variables are zero?', NULL, '["Beta Coefficient","Error Term","Intercept","Coefficient of Determination"]', 'Intercept', 'The intercept represents the expected value of the dependent variable when all independent variables equal zero.'),
(2, 3, 'Simple vs. Multiple Linear Regression', 'conceptual', 'multiple_choice', 'What is the primary difference between simple linear regression and multiple linear regression?', NULL, '["Simple regression predicts categorical outcomes.","Multiple regression uses two or more predictor variables.","Simple regression cannot make predictions.","Multiple regression has no dependent variable."]', 'Multiple regression uses two or more predictor variables.', 'Simple linear regression uses one predictor, while multiple linear regression uses two or more predictors.'),
(2, 3, 'Regression Model', 'conceptual', 'fill_in_blank', 'The symbol commonly used to represent the unexplained variation in a regression equation is the __________ term.', NULL, NULL, 'Error', 'The error term accounts for variability in the dependent variable not explained by the predictors.'),
(2, 3, 'Coefficient of Determination', 'conceptual', 'multiple_choice', 'Which metric measures the proportion of variability in the dependent variable explained by the regression model?', NULL, '["Mean Absolute Error (MAE)","Coefficient of Determination (R²)","Precision","Recall"]', 'Coefficient of Determination (R²)', 'R² measures how well the independent variables explain variation in the dependent variable.'),
(2, 3, 'Model Validation', 'conceptual', 'multiple_choice', 'A regression model has already been developed. According to the predictive analytics process, what should be evaluated before selecting the model for deployment?', NULL, '["Font size of the report","Model performance","Number of worksheets used","Database storage capacity"]', 'Model performance', 'Model validation evaluates the model''s predictive performance before it is selected for deployment.'),
(2, 3, 'Predictive Analytics', 'conceptual', 'multiple_choice', 'A hospital develops a model that predicts whether a patient is likely to be readmitted within 30 days. Which predictive modeling technique is most appropriate when the outcome is either "Yes" or "No"?', NULL, '["Simple Linear Regression","Multiple Linear Regression","Logistic Regression","Correlation Analysis"]', 'Logistic Regression', 'Logistic regression is designed for binary classification problems where the outcome has two possible categories.'),
(2, 3, 'Predictive Analytics Process', 'conceptual', 'multiple_choice', 'During which stage of the predictive analytics process are trends, anomalies, and relationships within the dataset examined before model building?', NULL, '["Project Design","Data Exploration","Model Validation","Deployment"]', 'Data Exploration', 'Data exploration involves examining the data to understand patterns, trends, anomalies, and relationships before modeling.'),
(2, 3, 'Multiple Linear Regression', 'conceptual', 'multiple_choice', 'A company predicts house prices using floor area, number of bedrooms, age of the house, and distance from the city center. Which type of regression model is being used?', NULL, '["Simple Linear Regression","Multiple Linear Regression","Logistic Regression","Correlation Analysis"]', 'Multiple Linear Regression', 'Multiple linear regression uses two or more independent variables to predict a continuous dependent variable.'),
(2, 3, 'Coefficient of Determination (R²)', 'conceptual', 'multiple_choice', 'A regression model has an R² value of 0.82. What does this indicate?', NULL, '["82% of the variability in the dependent variable is explained by the model.","82% of the predictions are perfectly accurate.","The model has an 82% probability of being correct.","The dependent variable increases by 82 units for every predictor."]', '82% of the variability in the dependent variable is explained by the model.', 'R² measures the proportion of variation in the dependent variable explained by the regression model.'),
(2, 3, 'Regression Coefficients', 'conceptual', 'identification', 'In a regression equation, the coefficient that represents the rate of change in the dependent variable for every unit increase in a predictor is called the __________ coefficient.', NULL, NULL, 'Beta', 'The beta coefficient represents the effect of an independent variable on the dependent variable.'),
(2, 3, 'Analysis of Variance (ANOVA)', 'conceptual', 'multiple_choice', 'In regression analysis, what is the primary purpose of ANOVA?', NULL, '["To calculate the regression equation","To determine how much variation is explained by the model compared to unexplained error","To identify outliers","To compute the correlation coefficient"]', 'To determine how much variation is explained by the model compared to unexplained error', 'ANOVA decomposes the total variation into explained (model) and unexplained (error) components.'),
(2, 3, 'Predictor Significance', 'conceptual', 'multiple_choice', 'A predictor variable has a p-value greater than 0.05 in a regression model. Based on the module, how is this predictor generally interpreted?', NULL, '["It is a statistically significant predictor.","It is not a statistically significant predictor.","It guarantees higher prediction accuracy.","It should always become the dependent variable."]', 'It is not a statistically significant predictor.', 'A predictor with a p-value greater than the significance level is generally considered statistically insignificant.'),
(2, 3, 'Forecast Accuracy Measures', 'conceptual', 'fill_in_blank', 'The forecast accuracy measure that calculates the average of the absolute prediction errors is called __________ Absolute Error (MAE).', NULL, NULL, 'Mean', 'Mean Absolute Error (MAE) measures the average magnitude of prediction errors regardless of direction.'),
(2, 3, 'Forecast Accuracy Measures', 'conceptual', 'multiple_choice', 'Which forecast accuracy measure expresses prediction error as a percentage, making it useful for comparing models across different scales?', NULL, '["MAE","RMSE","MAPE","MSE"]', 'MAPE', 'Mean Absolute Percentage Error (MAPE) expresses forecasting error as a percentage.'),
(2, 3, 'Logistic Regression', 'conceptual', 'multiple_choice', 'Which performance metric measures the proportion of actual positive cases that are correctly identified by a logistic regression model?', NULL, '["Accuracy","Recall","Precision","R²"]', 'Recall', 'Recall measures the percentage of actual positive instances correctly identified by the classifier.'),
(2, 3, 'Logistic Regression', 'conceptual', 'multiple_choice', 'Which evaluation tool summarizes the number of correct and incorrect classifications made by a logistic regression model?', NULL, '["Scatter Plot","Correlation Matrix","Confusion Matrix","Pivot Table"]', 'Confusion Matrix', 'A confusion matrix summarizes the classification results by comparing predicted and actual classes.'),
(2, 3, 'Predictive Analytics Process', 'conceptual', 'multiple_choice', 'According to the predictive analytics process presented in the module, which activity typically occurs immediately after Project Design?', NULL, '["Model Validation","Feature Selection","Data Sampling","Deployment"]', 'Data Sampling', 'After defining the project objectives, the next step is obtaining and preparing the necessary data through data sampling.'),
(2, 3, 'Regression Interpretation', 'conceptual', 'multiple_choice', 'In a regression equation, what does a positive beta coefficient indicate?', NULL, '["The dependent variable decreases as the predictor increases.","The dependent variable tends to increase as the predictor increases.","The predictor is statistically insignificant.","The regression model is invalid."]', 'The dependent variable tends to increase as the predictor increases.', 'A positive beta coefficient indicates a direct relationship between the predictor and the dependent variable while holding other predictors constant.'),
(2, 3, 'Regression Interpretation', 'conceptual', 'multiple_choice', 'In the regression model Sales = 5 + 2X, what does the value 5 represent?', NULL, '["The beta coefficient","The error term","The intercept","The coefficient of determination"]', 'The intercept', 'The intercept represents the predicted value of the dependent variable when all predictor variables are equal to zero.'),
(2, 3, 'Error Term', 'conceptual', 'identification', 'The component of a regression equation that accounts for unexplained variability is called the __________ term.', NULL, NULL, 'Error', 'The error term represents the portion of the dependent variable that cannot be explained by the predictors included in the model.'),
(2, 3, 'Model Validation', 'conceptual', 'multiple_choice', 'According to the predictive analytics process, why is model validation performed before selecting the final model?', NULL, '["To increase the amount of training data","To determine how well the model performs before deployment","To eliminate the need for feature selection","To convert continuous variables into categorical variables"]', 'To determine how well the model performs before deployment', 'Model validation evaluates predictive performance so that the most appropriate model can be selected.'),
(2, 3, 'Forecast Accuracy Measures', 'conceptual', 'multiple_choice', 'Which forecast accuracy measure gives greater weight to larger prediction errors because the errors are squared?', NULL, '["MAE","MAPE","RMSE","Median Absolute Error"]', 'RMSE', 'Root Mean Squared Error (RMSE) penalizes larger errors more heavily because it is based on squared prediction errors.'),
(2, 3, 'Logistic Regression', 'conceptual', 'fill_in_blank', 'Logistic regression is primarily used for __________ problems where the outcome variable consists of categories.', NULL, NULL, 'classification', 'Logistic regression predicts categorical outcomes and is commonly used for classification tasks.'),
(2, 3, 'Logistic Regression Metrics', 'conceptual', 'multiple_choice', 'Which evaluation metric represents the proportion of predicted positive cases that are actually positive?', NULL, '["Recall","Precision","Accuracy","R²"]', 'Precision', 'Precision measures the correctness of positive predictions made by the classification model.'),
(2, 3, 'Logistic Regression Metrics', 'conceptual', 'multiple_choice', 'Which metric considers both precision and recall by computing their harmonic mean?', NULL, '["Accuracy","ROC-AUC","F1-score","MAE"]', 'F1-score', 'The F1-score balances precision and recall into a single evaluation metric.'),
(2, 3, 'Logistic Regression Metrics', 'conceptual', 'multiple_choice', 'Which evaluation metric measures the overall ability of a classifier to distinguish between positive and negative classes across different thresholds?', NULL, '["Precision","Recall","ROC-AUC","MSE"]', 'ROC-AUC', 'ROC-AUC evaluates how well a classification model separates positive and negative classes regardless of the chosen threshold.'),
(2, 3, 'Predictive Analytics', 'conceptual', 'multiple_choice', 'According to the module, which activity is performed during the Data Exploration stage of the predictive analytics process?', NULL, '["Deploying the final model","Identifying trends, anomalies, and relationships within the data","Presenting the final report to stakeholders","Selecting the best forecast accuracy measure"]', 'Identifying trends, anomalies, and relationships within the data', 'During Data Exploration, analysts study the dataset to understand its characteristics before building predictive models.'),

(2, 4, 'Prescriptive Analytics', 'conceptual', 'multiple_choice', 'Which question is primarily answered by prescriptive analytics?', NULL, '["What happened?","Why did it happen?","What will happen?","What should we do?"]', 'What should we do?', 'Prescriptive analytics recommends the best course of action after considering possible alternatives and constraints.'),
(2, 4, 'Prescriptive Analytics', 'conceptual', 'multiple_choice', 'According to the evolution of analytics, which type of analytics immediately precedes prescriptive analytics?', NULL, '["Descriptive Analytics","Diagnostic Analytics","Predictive Analytics","Exploratory Analytics"]', 'Predictive Analytics', 'Prescriptive analytics builds upon predictive analytics by using forecasts to recommend optimal decisions.'),
(2, 4, 'Decision Optimization', 'conceptual', 'identification', 'The process of determining the best solution among several feasible alternatives while considering constraints is called __________.', NULL, NULL, 'Optimization', 'Optimization identifies the best possible solution while satisfying specified objectives and constraints.'),
(2, 4, 'Simulation vs. Optimization', 'conceptual', 'multiple_choice', 'Which statement best differentiates simulation from optimization?', NULL, '["Simulation finds the best solution, while optimization evaluates possible scenarios.","Simulation evaluates possible scenarios, while optimization searches for the best solution.","Simulation and optimization have identical purposes.","Optimization predicts future values, while simulation summarizes historical data."]', 'Simulation evaluates possible scenarios, while optimization searches for the best solution.', 'Simulation examines the outcomes of different scenarios, whereas optimization identifies the best alternative according to an objective.'),
(2, 4, 'What-If Analysis', 'conceptual', 'multiple_choice', 'A manager changes several input values to observe how projected profit changes without automatically finding the best answer. Which Excel prescriptive analytics tool is being used?', NULL, '["Solver","Goal Seek","What-If Analysis","Pivot Table"]', 'What-If Analysis', 'What-If Analysis allows users to explore the effects of changing assumptions on outcomes.'),
(2, 4, 'Goal Seek', 'conceptual', 'fill_in_blank', 'The Excel feature used to determine the input value required to achieve a specified output is called __________.', NULL, NULL, 'Goal Seek', 'Goal Seek works backward by finding the input value needed to produce a desired result.'),
(2, 4, 'Scenario Manager', 'conceptual', 'multiple_choice', 'Which Excel tool allows users to save and compare multiple sets of assumptions for the same worksheet model?', NULL, '["Solver","Scenario Manager","Pivot Table","Conditional Formatting"]', 'Scenario Manager', 'Scenario Manager stores multiple input combinations so that different business situations can be compared easily.'),
(2, 4, 'Solver', 'conceptual', 'multiple_choice', 'Which Excel prescriptive analytics tool is specifically designed to maximize, minimize, or achieve a target value while satisfying constraints?', NULL, '["Goal Seek","Scenario Manager","Solver","Data Validation"]', 'Solver', 'Solver performs optimization by finding the best solution subject to user-defined constraints.'),
(2, 4, 'Prescriptive Analytics Process', 'conceptual', 'multiple_choice', 'According to the module, which activity typically occurs immediately after predictive modeling in the prescriptive analytics workflow?', NULL, '["Action Recommendation","Scenario Analysis","Optimization","Data Collection"]', 'Scenario Analysis', 'After predictive models estimate future outcomes, scenario analysis evaluates multiple possible situations before optimization.'),
(2, 4, 'Business Applications', 'conceptual', 'multiple_choice', 'Which of the following is identified in the module as a business application of prescriptive analytics?', NULL, '["Image Compression","Inventory Optimization","Word Processing","Database Normalization"]', 'Inventory Optimization', 'The module highlights inventory optimization as a common application of prescriptive analytics in supply chain management.'),
(2, 4, 'Prescriptive Analytics', 'conceptual', 'multiple_choice', 'Which characteristic best distinguishes prescriptive analytics from descriptive, diagnostic, and predictive analytics?', NULL, '["It only summarizes historical data.","It identifies the causes of events.","It recommends actions to achieve desired outcomes.","It forecasts future values without suggesting actions."]', 'It recommends actions to achieve desired outcomes.', 'Prescriptive analytics extends predictive analytics by recommending the best course of action based on objectives and constraints.'),
(2, 4, 'Prescriptive Analytics Workflow', 'conceptual', 'multiple_choice', 'According to the module, what is the first step in the prescriptive analytics workflow?', NULL, '["Predictive Modeling","Scenario Analysis","Data Collection and Integration","Optimization"]', 'Data Collection and Integration', 'The workflow begins by gathering and integrating relevant historical and real-time data from multiple sources.'),
(2, 4, 'Simulation', 'conceptual', 'identification', 'The process of evaluating multiple possible situations and their outcomes before selecting a decision is known as __________ analysis.', NULL, NULL, 'Scenario', 'Scenario analysis evaluates different possible situations and their implications before optimization.'),
(2, 4, 'Optimization', 'conceptual', 'multiple_choice', 'Which stage of the prescriptive analytics workflow determines the best solution among feasible alternatives?', NULL, '["Scenario Analysis","Optimization","Data Collection","Action Recommendation"]', 'Optimization', 'Optimization applies mathematical techniques to determine the best solution while considering objectives and constraints.'),
(2, 4, 'Machine Learning & AI', 'conceptual', 'multiple_choice', 'According to the module, machine learning contributes to prescriptive analytics primarily by:', NULL, '["Replacing optimization algorithms","Learning patterns from data to improve predictions over time","Displaying spreadsheet charts","Storing historical records"]', 'Learning patterns from data to improve predictions over time', 'Machine learning enables systems to learn from historical data and improve predictive capabilities that support decision recommendations.'),
(2, 4, 'Natural Language Processing', 'conceptual', 'fill_in_blank', 'The technology that enables systems to understand and communicate recommendations in human language is called __________ Language Processing.', NULL, NULL, 'Natural', 'Natural Language Processing (NLP) allows systems to interpret and communicate using human language.'),
(2, 4, 'Business Applications', 'conceptual', 'multiple_choice', 'Which business application of prescriptive analytics focuses on selecting the best routes and managing inventory efficiently?', NULL, '["Healthcare","Supply Chain","Financial Services","Energy and Utilities"]', 'Supply Chain', 'The module identifies inventory optimization and logistics routing as common supply chain applications.'),
(2, 4, 'Decision Making', 'conceptual', 'multiple_choice', 'According to the module, which benefit of prescriptive analytics allows organizations to evaluate numerous variables and constraints simultaneously?', NULL, '["Competitive Advantage","Reduced Decision Complexity","Improved Data Storage","Historical Reporting"]', 'Reduced Decision Complexity', 'Prescriptive analytics simplifies complex decision-making by evaluating many variables and constraints at once.'),
(2, 4, 'Implementation Challenges', 'conceptual', 'multiple_choice', 'Which implementation challenge involves combining information from multiple systems with different formats and quality levels?', NULL, '["Technology Selection","Data Integration","Skill Gaps","Organizational Change"]', 'Data Integration', 'Data integration is a common implementation challenge because organizations often store data in disparate systems.'),
(2, 4, 'Future Trends', 'conceptual', 'multiple_choice', 'According to the module, which emerging trend refers to systems that can implement recommended actions with minimal human intervention?', NULL, '["Explainable AI","Augmented Analytics","Autonomous Decision Systems","Edge Computing"]', 'Autonomous Decision Systems', 'Autonomous Decision Systems represent a future trend in which systems not only recommend actions but can also execute them with minimal human involvement.'),
(2, 4, 'Real-time Analytics', 'conceptual', 'multiple_choice', 'According to the module, what is the primary purpose of real-time analytics in prescriptive analytics?', NULL, '["To archive historical data","To process data as it is generated and provide immediate recommendations","To replace predictive models","To improve spreadsheet formatting"]', 'To process data as it is generated and provide immediate recommendations', 'Real-time analytics processes incoming data immediately so organizations can make timely decisions.'),
(2, 4, 'Optimization Algorithms', 'conceptual', 'multiple_choice', 'Which technology in prescriptive analytics is specifically responsible for finding the best solution while considering objectives and constraints?', NULL, '["Machine Learning","Optimization Algorithms","Natural Language Processing","Edge Computing"]', 'Optimization Algorithms', 'Optimization algorithms mathematically determine the best feasible solution among alternatives.'),
(2, 4, 'Simulation Modeling', 'conceptual', 'identification', 'Creating virtual scenarios to evaluate different strategies before implementation is known as __________ modeling.', NULL, NULL, 'Simulation', 'Simulation modeling allows organizations to evaluate possible outcomes before making real-world decisions.'),
(2, 4, 'Healthcare Applications', 'conceptual', 'multiple_choice', 'Which of the following is identified in the module as a healthcare application of prescriptive analytics?', NULL, '["Website Optimization","Patient Treatment Optimization","Social Media Monitoring","Database Replication"]', 'Patient Treatment Optimization', 'The module lists patient treatment optimization, staff scheduling, and resource allocation as healthcare applications.'),
(2, 4, 'Decision Making', 'conceptual', 'multiple_choice', 'Which benefit of prescriptive analytics enables organizations to make decisions more quickly through automated analysis and recommendation generation?', NULL, '["Reduced Decision Complexity","Increased Decision Speed","Improved Data Collection","Scenario Comparison"]', 'Increased Decision Speed', 'Automation allows prescriptive analytics to produce recommendations more rapidly than manual analysis.'),
(2, 4, 'Implementation Challenges', 'conceptual', 'fill_in_blank', 'According to the module, investing in training programs and cross-functional teams helps address __________ gaps.', NULL, NULL, 'Skill', 'Skill gaps are a common implementation challenge, and training helps organizations build the necessary expertise.'),
(2, 4, 'Organizational Change', 'conceptual', 'multiple_choice', 'Which best practice is recommended to help organizations transition from intuition-based decisions to data-driven decision making?', NULL, '["Purchase more hardware","Start with high-impact use cases and demonstrate return on investment","Reduce employee involvement","Eliminate predictive analytics"]', 'Start with high-impact use cases and demonstrate return on investment', 'Demonstrating successful, high-impact projects encourages organizational acceptance of data-driven decision making.'),
(2, 4, 'Technology Selection', 'conceptual', 'multiple_choice', 'According to the module, what is the recommended approach when selecting prescriptive analytics technologies?', NULL, '["Adopt the newest technology immediately","Begin with pilot projects to evaluate technology fit","Choose the least expensive software available","Avoid testing before deployment"]', 'Begin with pilot projects to evaluate technology fit', 'Pilot projects allow organizations to determine whether a technology meets business requirements before full implementation.'),
(2, 4, 'Future Trends', 'conceptual', 'multiple_choice', 'Which emerging trend focuses on making advanced analytics accessible to non-technical business users through AI-powered tools?', NULL, '["Autonomous Decision Systems","Edge Computing","Augmented Analytics","Simulation Modeling"]', 'Augmented Analytics', 'Augmented analytics uses AI to simplify advanced analytical tasks for business users.'),
(2, 4, 'Future Trends', 'conceptual', 'multiple_choice', 'Which future trend emphasizes making AI recommendations transparent by explaining how conclusions are generated?', NULL, '["Natural Language Processing","Explainable AI","Optimization Algorithms","Scenario Analysis"]', 'Explainable AI', 'Explainable AI improves trust by providing understandable reasons behind AI-generated recommendations.');



-- ============================================================================
-- QUESTION BATCH #2 (114 Questions)
-- ============================================================================
INSERT INTO questions (course_id, module_num, topic, category, question_type, question_text, code_snippet, options, correct_answer, explanation) VALUES
-- MODULE 1
(3, 1, 'Software Definition', 'conceptual', 'multiple_choice', 'Which component enables computer programs to adequately manipulate information within a software system?', NULL, '["Data structures", "Hardware buses", "Power supplies", "Network switches"]', 'Data structures', 'Data structures (such as databases) enable programs to manipulate information effectively.'),
(3, 1, 'Software Questions', 'conceptual', 'multiple_choice', 'Which of the following is a fundamental challenge addressed in software engineering regarding development timelines?', NULL, '["Why does it take so long to finish a software?", "Why is hardware getting smaller every year?", "Why are programming languages updated weekly?", "Why do users reject touchscreens?"]', 'Why does it take so long to finish a software?', 'Software development questions focus on understanding timeline delays, high development costs, pre-release defect elimination, and maintenance challenges.'),
(3, 1, 'Software Questions', 'conceptual', 'multiple_choice', 'What is a major issue related to software post-release?', NULL, '["High effort and time spent to maintain existing software", "Inability to run on cloud platforms", "Lack of keyboard support", "Hardware degradation over time"]', 'High effort and time spent to maintain existing software', 'Software engineering addresses why significant time and effort are spent on maintaining existing software products.'),
(3, 1, 'Software Categories', 'conceptual', 'multiple_choice', 'Which software category relies on broad "number crunching" algorithms?', NULL, '["Engineering/Scientific Software", "System Software", "Product-line Software", "Web Applications"]', 'Engineering/Scientific Software', 'Engineering and scientific software involves intensive numeric computation and algorithms.'),
(3, 1, 'Software Categories', 'conceptual', 'multiple_choice', 'Software designed to provide specific capabilities for use by many different customers is classified as:', NULL, '["System Software", "Embedded Software", "Product-line Software", "Artificial Intelligence Software"]', 'Product-line Software', 'Product-line software is crafted to provide a standardized set of capabilities across multiple clients in a target market.'),
(3, 1, 'Software Categories', 'conceptual', 'multiple_choice', 'Which software category utilizes non-numerical algorithms to solve complex problems that are not amenable to straightforward computation?', NULL, '["Artificial Intelligence Software", "Engineering Software", "System Software", "Application Software"]', 'Artificial Intelligence Software', 'Artificial Intelligence software uses non-numerical problem-solving algorithms for complex tasks.'),
(3, 1, 'Legacy Software', 'conceptual', 'multiple_choice', 'Why do legacy systems present ongoing operational challenges to organizations?', NULL, '["They can be costly to maintain and risky to evolve", "They lack documentation for installation", "They cannot run on electronic processors", "They operate without database connections"]', 'They can be costly to maintain and risky to evolve', 'Legacy software systems are often delicate, expensive to maintain, and carry risk when modified.'),
(3, 1, 'Infants Software', 'conceptual', 'multiple_choice', 'Which software type is characterized as network-centric applications encompassing browser-based and mobile interfaces?', NULL, '["WebApps and Mobile Applications", "System Software", "Engineering Software", "Embedded Firmware"]', 'WebApps and Mobile Applications', 'WebApps and Mobile Applications represent modern "infant" software technologies that utilize network interfaces and unique device interactions.'),
(3, 1, 'Software Realities', 'conceptual', 'multiple_choice', 'According to software realities, what happens to the perceived value of a specific software application as its user base expands?', NULL, '["It grows as its user base grows", "It rapidly decreases to zero", "It remains completely unchanged", "It becomes obsolete immediately"]', 'It grows as its user base grows', 'Network effects and utility dictate that a software application''s perceived value grows alongside its user base.'),
(3, 1, 'Software Engineering Layers', 'conceptual', 'multiple_choice', 'In the software engineering layered technology framework, what lies at the base driving organizational philosophy?', NULL, '["Quality Focus", "Tools", "Methods", "Compilers"]', 'Quality Focus', 'Any engineering approach must rest on an organizational commitment to quality focus.'),
(3, 1, 'Software Process Definitions', 'conceptual', 'multiple_choice', 'In software engineering terminology, how is an "Activity" distinguished from a "Task"?', NULL, '["An activity strives to achieve a broad objective, while a task focuses on small, well-defined objectives to produce a tangible outcome", "A task is broader than an activity", "An activity deals only with testing", "Tasks do not produce work products"]', 'An activity strives to achieve a broad objective, while a task focuses on small, well-defined objectives to produce a tangible outcome', 'Activities target broad high-level objectives, whereas tasks are granular, targeted actions delivering specific outcomes.'),
(3, 1, 'Process Framework', 'conceptual', 'multiple_choice', 'Which framework phase involves creating a "sketch" or blueprint of the project to understand the big picture and requirements?', NULL, '["Modeling", "Deployment", "Construction", "Planning"]', 'Modeling', 'Modeling produces architectural designs, diagrams, and requirement blueprints ("sketches") of the software system.'),
(3, 1, 'Process Framework', 'conceptual', 'multiple_choice', 'Which process framework phase delivers the software product to the customer for evaluation and feedback?', NULL, '["Deployment", "Planning", "Modeling", "Construction"]', 'Deployment', 'Deployment delivers working software to end users, who evaluate it and provide operational feedback.'),
(3, 1, 'Software Engineering Practice', 'conceptual', 'multiple_choice', 'What is the initial step in generic software engineering practice before planning a solution?', NULL, '["Understand the Problem (Communication and Analysis)", "Code generation", "Testing and Quality Assurance", "Deployment"]', 'Understand the Problem (Communication and Analysis)', 'Engineers must first understand the problem through communication and requirement analysis prior to designing solutions.'),
(3, 1, 'Software Engineering Principles', 'conceptual', 'multiple_choice', 'The software engineering principle "KISS" emphasizes which design philosophy?', NULL, '["Keep It Simple, Stupid - all design should be as simple as possible, but no simpler", "Keep Interfaces System-Specific", "Know Important System Secrets", "Key Integration Software Steps"]', 'Keep It Simple, Stupid - all design should be as simple as possible, but no simpler', 'KISS advocates for simplicity in system architecture and software design.'),
(3, 1, 'Software Engineering Principles', 'conceptual', 'multiple_choice', 'What is the overarching reason why software systems exist?', NULL, '["To provide value to its users", "To maximize line counts of code", "To utilize complex hardware", "To generate theoretical documentation"]', 'To provide value to its users', 'The fundamental principle of software engineering is that software exists solely to deliver value to its end users.'),
(3, 1, 'Software Engineering Principles', 'conceptual', 'multiple_choice', 'A lead architect designs a system component with modular plug-ins and clean interface abstractions specifically so that future developers can extend features without rewriting the core engine. Which software engineering principle is primarily applied here?', NULL, '["Be open to the Future and plan ahead for reuse", "Build for single-use deployment", "Minimize user communication", "Avoid abstraction"]', 'Be open to the Future and plan ahead for reuse', 'Designing for flexibility prevents locking the system into a corner and maximizes long-term software asset reuse.'),
(3, 1, 'Software Engineering Practice', 'conceptual', 'multiple_choice', 'During a software development project, a developer writes comprehensive unit test suites and conducts code reviews before shipping code. Under which practice area does this fall?', NULL, '["Examine the result for accuracy (Testing and Quality Assurance)", "Communication and Analysis", "Code generation only", "Requirements Scoping"]', 'Examine the result for accuracy (Testing and Quality Assurance)', 'Validating that code operates correctly and meets quality metrics corresponds to the practice of examining results for accuracy.'),
(3, 1, 'Software Definition', 'conceptual', 'multiple_choice', 'Which best describes software?', NULL, '["Only the physical components of a computer", "A collection of computer programs, procedures, and documentation that perform tasks on a computer system", "A device used to store information", "A network connection between computers"]', 'A collection of computer programs, procedures, and documentation that perform tasks on a computer system', 'Software is defined as a collection of computer programs, procedures, and documentation that perform tasks on a computer system.'),
(3, 1, 'Software Categories', 'conceptual', 'multiple_choice', 'Which type of software is a collection of programs written to service other programs?', NULL, '["Application Software", "Embedded Software", "System Software", "Product-line Software"]', 'System Software', 'System software is a collection of programs written to service other programs.'),
(3, 1, 'Software Categories', 'conceptual', 'multiple_choice', 'Which software category usually consists of stand-alone programs that solve specific business needs?', NULL, '["Application Software", "System Software", "Engineering Software", "Embedded Software"]', 'Application Software', 'Application software usually consists of stand-alone programs that solve specific business needs.'),
(3, 1, 'Software Categories', 'conceptual', 'multiple_choice', 'Which type of software resides within a product or system and implements control features?', NULL, '["Web Application", "Embedded Software", "Application Software", "Product-line Software"]', 'Embedded Software', 'Embedded software resides within a product or system and implements control features for the user and system itself.'),
(3, 1, 'Legacy Software', 'conceptual', 'multiple_choice', 'What is a major characteristic of legacy software?', NULL, '["It was developed only for mobile devices.", "It cannot be modified.", "It consists of older programs developed decades ago.", "It is always inexpensive to maintain."]', 'It consists of older programs developed decades ago.', 'Legacy software consists of older programs that were developed decades ago and are continually modified to meet business changes.'),
(3, 1, 'Infants Software', 'conceptual', 'multiple_choice', 'Which is considered an "infant" software technology in the module?', NULL, '["Legacy Software", "WebApps", "System Software", "Engineering Software"]', 'WebApps', 'WebApps and Mobile Applications are categorized as "infant" software technologies in the module.'),
(3, 1, 'Infants Software', 'conceptual', 'multiple_choice', 'What does cloud computing enable users to do?', NULL, '["Use computing resources only from one location", "Share or use computing resources on a broad scale from anywhere or anytime", "Eliminate the need for computing devices", "Use only stand-alone applications"]', 'Share or use computing resources on a broad scale from anywhere or anytime', 'Cloud computing encompasses an infrastructure that enables users from anywhere or anytime to share or use computing resources on a broad scale.'),
(3, 1, 'Software Engineering', 'conceptual', 'multiple_choice', 'Software engineering is best described as:', NULL, '["The physical repair of computer hardware", "A process, collection of methods, and tools for building high-quality computer software", "The process of purchasing computer programs", "The study of computer networks only"]', 'A process, collection of methods, and tools for building high-quality computer software', 'Software engineering is a process or collection of methods and an array of tools that allow professionals to build high quality computer software.'),
(3, 1, 'Software Engineering Principles', 'conceptual', 'multiple_choice', 'Which two qualities are required in software engineering according to the module?', NULL, '["Speed and complexity", "Adaptability and agility", "Cost and size", "Hardware and networking"]', 'Adaptability and agility', 'According to the module, both adaptability and agility are required in software engineering.'),
(3, 1, 'Software Engineering Layers', 'conceptual', 'multiple_choice', 'What is the foundation of software engineering as a layered technology?', NULL, '["Tools", "Methods", "Process", "Programming"]', 'Process', 'Software engineering is a layered technology and its foundation is the process layer.'),

-- MODULE 2
(3, 2, 'System Definition', 'conceptual', 'multiple_choice', 'How is a "System" formally defined in software engineering and IS context?', NULL, '["A set of interacting or interdependent entities forming an integrated whole performing specific functions", "A single isolated computer program", "A hardware processor chip", "A database query language"]', 'A set of interacting or interdependent entities forming an integrated whole performing specific functions', 'A system comprises integrated, interdependent components that interact to execute designated functions.'),
(3, 2, 'System Types', 'conceptual', 'multiple_choice', 'Which type of system produces predictable outputs from measured inputs with certainty?', NULL, '["Closed System", "Open System", "Probabilistic System", "Dynamic System"]', 'Closed System', 'Closed systems yield predictable, deterministic outputs based on known inputs.'),
(3, 2, 'System Types', 'conceptual', 'multiple_choice', 'Which type of system is characterized as probabilistic because outputs cannot be determined precisely until the actual event occurs?', NULL, '["Open System", "Closed System", "Deterministic System", "Static System"]', 'Open System', 'Open systems interact with uncertain external environments, making their outcomes probabilistic.'),
(3, 2, 'Information System Definition', 'conceptual', 'multiple_choice', 'An Information System (IS) is best defined as:', NULL, '["A set of interrelated components that collect, store, process, and analyze data to support decision-making and control", "A standalone compiler program", "A physical network cabling infrastructure", "An automated graphic design tool"]', 'A set of interrelated components that collect, store, process, and analyze data to support decision-making and control', 'Information Systems combine data, process, people, and technology to collect and process organizational data.'),
(3, 2, 'IS Activities', 'conceptual', 'multiple_choice', 'What are the four primary activities in an Information System execution loop?', NULL, '["Input, Process, Output, Feedback", "Create, Read, Update, Delete", "Plan, Design, Code, Test", "Initiate, Execute, Monitor, Close"]', 'Input, Process, Output, Feedback', 'The operational loop of an Information System consists of Inputting raw data, Processing it, Outputting information, and gathering Feedback.'),
(3, 2, 'IS Resource Approach', 'conceptual', 'multiple_choice', 'In the IS resource lifecycle approach, what operations are performed on data?', NULL, '["Create, Process, Update, Retrieve, Destroy", "Compile, Link, Execute, Debug", "Input, Output, Feedback, Loop", "Design, Build, Deploy, Maintain"]', 'Create, Process, Update, Retrieve, Destroy', 'Data handling lifecycle steps involve creating, processing, updating, retrieving, and eventually destroying data.'),
(3, 2, 'Good Information Characteristics', 'conceptual', 'multiple_choice', 'Which of the following is a key characteristic of good information?', NULL, '["Accuracy, Timeliness, Less Uncertainty, and Decision-making aid", "Maximum complexity and high volume", "Redundancy and ambiguity", "Infinite delay and high cost"]', 'Accuracy, Timeliness, Less Uncertainty, and Decision-making aid', 'Quality information must be accurate, timely, reduce uncertainty, and support informed managerial decisions.'),
(3, 2, 'IS Major Components', 'conceptual', 'multiple_choice', 'Which component of an Information System consists of raw, unanalyzed facts?', NULL, '["Data", "Information", "Process", "Knowledge Base"]', 'Data', 'Data represents raw facts that have not yet been structured or processed into meaningful information.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'Which type of Information System is primarily used for operational record-keeping and routine transaction processing like payroll and sales orders?', NULL, '["Transaction Processing System (TPS)", "Decision Support System (DSS)", "Executive Information System (EIS)", "Expert System"]', 'Transaction Processing System (TPS)', 'TPS records daily operational transactions such as sales orders, payroll, and inventory transfers.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'Which system provides senior executives with trend analysis, exception reporting, and drill-down graphical capabilities?', NULL, '["Executive Information System (EIS)", "Transaction Processing System (TPS)", "Workflow System", "Data Entry System"]', 'Executive Information System (EIS)', 'EIS provides high-level executive dashboards, drill-down tools, and trend summaries for senior leaders.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'Which Information System supports complex, problem-specific decision-making using sophisticated analytical tools and external data feeds?', NULL, '["Decision Support System (DSS)", "Management Information System (MIS)", "Transaction Processing System (TPS)", "Ad-hoc System"]', 'Decision Support System (DSS)', 'DSS offers data models and analytical tools to assist managers with non-routine, complex decisions.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'Administrative, Ad-hoc, and Production systems are categories belonging to which type of Information System?', NULL, '["Workflow Systems", "Transaction Processing Systems", "Expert Systems", "Database Management Systems"]', 'Workflow Systems', 'Workflow systems coordinate structured tasks and include administrative, ad-hoc, and production workflows.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'An Enterprise Resource Planning (ERP) system is designed to:', NULL, '["Manage vital business operations across an entire multi-site or global organization using integrated software programs", "Process graphics for video games", "Replace low-level network drivers", "Automate single-user spreadsheet generation"]', 'Manage vital business operations across an entire multi-site or global organization using integrated software programs', 'ERP integrates core enterprise functions across facilities and departments into a single system.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'Which system utilizes an extensive knowledge base to offer expert-level suggestions and solutions within a specific domain?', NULL, '["Expert System", "Transaction Processing System", "Management Information System", "File Server"]', 'Expert System', 'Expert Systems replicate domain expertise using rule bases and knowledge engines.'),
(3, 2, 'SDLC Overview', 'conceptual', 'multiple_choice', 'What is the System Development Life Cycle (SDLC)?', NULL, '["A structured process for planning, creating, testing, deploying, and maintaining an information system", "A manual for installing computer hardware", "A programming language syntax guide", "A financial audit process"]', 'A structured process for planning, creating, testing, deploying, and maintaining an information system', 'SDLC provides an end-to-end framework governing the development lifecycle of IT systems.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'How many standard phases comprise the traditional SDLC described in the module?', NULL, '["7 phases", "3 phases", "10 phases", "5 phases"]', '7 phases', 'The standard SDLC encompasses 7 key phases: Planning, Analysis, Design, Development, Testing, Implementation, and Maintenance.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'In which SDLC phase is a preliminary feasibility study conducted to evaluate project scope, costs, and resources?', NULL, '["Planning Phase", "Systems Analysis Phase", "System Development Phase", "System Maintenance Phase"]', 'Planning Phase', 'Feasibility studies, scoping, resource planning, and cost-benefit evaluations occur in the Planning phase.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'During which SDLC phase are user requirements gathered and analyzed using tools like CASE and structured analysis?', NULL, '["Systems Analysis Phase", "Systems Design Phase", "System Implementation Phase", "System Testing Phase"]', 'Systems Analysis Phase', 'The Analysis phase identifies root problems and establishes detailed user functional requirements.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'Which SDLC phase translates functional requirements into detailed hardware, software, network, and procedure specifications?', NULL, '["Systems Design Phase", "System Maintenance Phase", "Planning Phase", "System Testing Phase"]', 'Systems Design Phase', 'Systems Design converts functional needs into technical architectural blueprints and component specifications.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'In which SDLC phase are network engineers, database developers, and programmers engaged to construct system components?', NULL, '["System Development Phase", "Planning Phase", "Maintenance Phase", "Feasibility Phase"]', 'System Development Phase', 'The Development phase is where code construction, database creation, and hardware staging take place.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'Verification and validation activities performed by QA professionals occur primarily in which SDLC phase?', NULL, '["System Testing Phase", "Planning Phase", "Analysis Phase", "System Maintenance Phase"]', 'System Testing Phase', 'Quality assurance testing validates system interoperability, correctness, and absence of defects.'),
(3, 2, 'SDLC Phases', 'conceptual', 'multiple_choice', 'Which SDLC phase involves direct cutover during off-peak hours to transition data and operations to the production system?', NULL, '["System Implementation Phase", "System Design Phase", "Planning Phase", "Feasibility Phase"]', 'System Implementation Phase', 'Implementation installs the system in production, migrating legacy data and cutover operations.'),
(3, 2, 'SDLC vs Software DLC', 'conceptual', 'multiple_choice', 'What is the primary difference between System Development Life Cycle and Software Development Life Cycle?', NULL, '["System DLC encompasses people, process, software, and hardware deployment, while Software DLC focuses strictly on software components", "Software DLC includes hardware construction", "System DLC applies only to mobile apps", "There is no difference between them"]', 'System DLC encompasses people, process, software, and hardware deployment, while Software DLC focuses strictly on software components', 'System DLC is a broader superset encompassing people, organizational change, hardware, and software, whereas Software DLC concentrates on software assets.'),
(3, 2, 'Project Management Frameworks', 'conceptual', 'multiple_choice', 'What are the four components of the "Four P''s Approach" in project management?', NULL, '["Plan, Process, People, Power", "Product, Price, Place, Promotion", "Planning, Programming, Prototyping, Production", "Process, Performance, People, Profit"]', 'Plan, Process, People, Power', 'The Four P''s approach emphasizes Plan (forecasting), Process (governance), People (collaboration), and Power (authority).'),
(3, 2, 'Project Management Phases', 'conceptual', 'multiple_choice', 'In which project management phase is the Project Charter developed to formally authorize the endeavor?', NULL, '["Initiation Phase", "Execution Phase", "Closing Phase", "Monitoring Phase"]', 'Initiation Phase', 'Developing the project charter and defining preliminary scope occur during project Initiation.'),
(3, 2, 'Umbrella Activities', 'conceptual', 'multiple_choice', 'Which software project umbrella activity focuses on managing the effects of changes throughout the software process?', NULL, '["Configuration Management", "Reusability Management", "Quality Assurance", "Technical Review"]', 'Configuration Management', 'Configuration management tracks, controls, and manages updates to software artifacts and versions.'),
(3, 2, 'System Analysis Overview', 'conceptual', 'multiple_choice', 'How is "Analysis" distinguished from "Synthesis"?', NULL, '["Analysis breaks down a whole into component parts, whereas synthesis combines separate elements into a coherent whole", "Analysis combines parts into a system", "Synthesis breaks down problems", "Analysis applies only to hardware"]', 'Analysis breaks down a whole into component parts, whereas synthesis combines separate elements into a coherent whole', 'Analysis decomposes complex domains into parts; synthesis reassembles elements into an integrated solution.'),
(3, 2, 'Computer Science Trends', 'conceptual', 'multiple_choice', 'Which emerging computer science research area applies programming and data analytics to massive datasets of biological and genetic information?', NULL, '["Bioinformatics", "Cyber Security", "Computer-Assisted Education", "Robotics"]', 'Bioinformatics', 'Bioinformatics merges computer science, algorithms, and biological data processing.'),
(3, 2, 'Types of Information Systems', 'conceptual', 'multiple_choice', 'A regional retail enterprise experiences a major disconnect: store managers manually email weekly sales spreadsheets to regional directors, who manually combine them into monthly slides. To address this bottleneck, which system should the company implement to automatically consolidate data from daily sales transactions into standardized management reports?', NULL, '["Management Information System (MIS)", "Expert System", "Ad-hoc Workflow System", "Computer-Aided Software Engineering (CASE) Tool"]', 'Management Information System (MIS)', 'MIS consolidates daily operational data from Transaction Processing Systems to deliver routine summary reports to management.'),
(3, 2, 'Project Management Scheduling', 'conceptual', 'multiple_choice', 'A software team is scheduling a complex cloud migration project where several task durations are uncertain. To identify the minimum time required to complete the total project and assess task dependencies, which technique should they use?', NULL, '["PERT Chart", "BPMN Diagram", "UseCase Grid", "Fact-finding Questionnaire"]', 'PERT Chart', 'PERT charts analyze task sequences, estimated completion times, and dependencies to derive the minimum total project duration.'),
(3, 2, 'Project Management - Umbrella Activities', 'conceptual', 'multiple_choice', 'During a software project, the development team establishes automated regression test suites, continuous integration checks, and mandatory peer code reviews before merging code to master. Which umbrella activity is directly being performed?', NULL, '["Quality Assurance", "Reusability Management", "Contract Closure", "Scope Definition"]', 'Quality Assurance', 'Quality Assurance encompasses activities that verify work products meet established quality standards and catch errors early.'),
(3, 2, 'Project Management', 'conceptual', 'multiple_choice', 'Which statement best defines a project?', NULL, '["A permanent activity performed every day", "A temporary endeavor designed to produce a unique product or service", "A routine activity without a specific goal", "An activity with no beginning or end"]', 'A temporary endeavor designed to produce a unique product or service', 'A project is a temporary endeavor designed to produce a unique product or service with a defined beginning and end.'),
(3, 2, 'Project Management', 'conceptual', 'multiple_choice', 'Which of the following is NOT considered a project?', NULL, '["Creating a unique software application", "Developing a new service", "Performing routine activities", "Constructing a new system"]', 'Performing routine activities', 'Activities that are undertaken to accomplish routine activities cannot be considered projects.'),
(3, 2, 'Project Management', 'conceptual', 'multiple_choice', 'Project management is the practice of:', NULL, '["Programming software only", "Initiating, planning, executing, controlling, and closing the work of a team", "Hiring employees only", "Performing routine activities without planning"]', 'Initiating, planning, executing, controlling, and closing the work of a team', 'Project management is the practice of initiating, planning, executing, controlling, and closing the work of a team to achieve specific goals.'),
(3, 2, 'Project Management', 'conceptual', 'multiple_choice', 'What is the primary challenge of project management?', NULL, '["Avoiding project documentation", "Increasing the number of team members", "Achieving project goals within given constraints", "Removing all project deadlines"]', 'Achieving project goals within given constraints', 'The primary challenge of project management is to achieve all of the project goals within the given constraints.'),
(3, 2, 'Project Manager Role', 'conceptual', 'multiple_choice', 'Who is accountable for accomplishing the stated project objectives?', NULL, '["Customer", "Project Manager", "Programmer only", "End user"]', 'Project Manager', 'Project managers are the people accountable for accomplishing the stated project objectives.'),
(3, 2, 'Project Management Forefathers', 'conceptual', 'multiple_choice', 'Who is known as the father of planning and control techniques and is famous for the Gantt Chart?', NULL, '["Henri Fayol", "Henry Gantt", "Frederick Taylor", "Robert Pressman"]', 'Henry Gantt', 'Henry Gantt is called the father of planning and control techniques and is famous for his use of the Gantt Chart.'),
(3, 2, 'Gantt Chart', 'conceptual', 'multiple_choice', 'In the Gantt Chart shown in the module, the red marks indicate the:', NULL, '["Shortest task", "Completed tasks", "Critical path or longest stretch of the project", "Project budget"]', 'Critical path or longest stretch of the project', 'Red marks in the Gantt chart indicate the critical path or the longest stretch of the project.'),
(3, 2, 'PERT Chart', 'conceptual', 'multiple_choice', 'What does PERT stand for?', NULL, '["Project Evaluation and Resource Tracking", "Program/Project Evaluation and Review Technique", "Planning, Execution, Review, and Testing", "Project Engineering and Research Technique"]', 'Program/Project Evaluation and Review Technique', 'PERT stands for Program/Project Evaluation and Review Technique.'),
(3, 2, 'PERT Chart', 'conceptual', 'multiple_choice', 'What is a PERT Chart primarily used for?', NULL, '["Designing computer interfaces", "Scheduling, organizing, and coordinating project tasks", "Writing program code", "Creating financial statements"]', 'Scheduling, organizing, and coordinating project tasks', 'A PERT chart is a project management tool used to schedule, organize, and coordinate tasks within a project.'),
(3, 2, 'System Analysis', 'conceptual', 'multiple_choice', 'What does "analysis" mean in system analysis?', NULL, '["Combining separate elements into a whole", "Breaking down a whole into parts", "Removing all system components", "Creating a final product immediately"]', 'Breaking down a whole into parts', 'Analysis is defined as the procedure by which we break down an intellectual or substantial whole into parts.'),

-- MODULE 3
(3, 3, 'Scrum Framework', 'conceptual', 'multiple_choice', 'What is Scrum in the context of Agile software development?', NULL, '["An agile process framework for managing complex knowledge work using timeboxed iterations called sprints", "A programming language syntax", "A waterfall testing tool", "A database design standard"]', 'An agile process framework for managing complex knowledge work using timeboxed iterations called sprints', 'Scrum is an agile framework based on timeboxed sprints, daily standups, and iterative product increments.'),
(3, 3, 'Scrum Roles', 'conceptual', 'multiple_choice', 'Which Scrum role is responsible for representing customer stakeholders, prioritizing the product backlog, and ensuring value delivery?', NULL, '["Product Owner", "Scrum Master", "Development Team Member", "Project Sponsor"]', 'Product Owner', 'The Product Owner manages and prioritizes the Product Backlog to align development with business value.'),
(3, 3, 'Scrum Roles', 'conceptual', 'multiple_choice', 'Which Scrum role acts as a facilitator, enforcing Scrum rules, removing team impediments, and coaching team members?', NULL, '["Scrum Master", "Product Owner", "Lead Developer", "QA Manager"]', 'Scrum Master', 'The Scrum Master facilitates events, removes blockers, and ensures Scrum principles are applied.'),
(3, 3, 'Scrum Roles', 'conceptual', 'multiple_choice', 'What is the recommended team size for a Scrum Development Team?', NULL, '["3 to 10 individuals", "20 to 50 individuals", "Exactly 1 person", "Unlimited members"]', '3 to 10 individuals', 'Scrum teams are intentionally small and self-organizing, typically comprising 3 to 10 cross-functional members.'),
(3, 3, 'Scrum Ceremonies', 'conceptual', 'multiple_choice', 'What is the maximum timebox for a Daily Scrum meeting?', NULL, '["15 minutes", "1 hour", "30 minutes", "4 hours"]', '15 minutes', 'Daily Scrums are strictly timeboxed to 15 minutes to synchronize daily tasks and identify blockers.'),
(3, 3, 'Scrum Ceremonies', 'conceptual', 'multiple_choice', 'During a Daily Scrum, which three questions does each development team member answer?', NULL, '["What was completed yesterday? What will be done today? What impediments exist?", "What is the budget? Who is to blame? When is the launch?", "How many lines of code were written? Who logged in? What bugs exist?", "What was designed? What was documented? Who signed off?"]', 'What was completed yesterday? What will be done today? What impediments exist?', 'Daily standups focus on immediate past accomplishments, planned daily work, and identified impediments.'),
(3, 3, 'Scrum Ceremonies', 'conceptual', 'multiple_choice', 'Which Scrum event occurs at the end of a sprint to demonstrate completed increments to stakeholders and gather feedback?', NULL, '["Sprint Review", "Sprint Retrospective", "Daily Standup", "Backlog Refinement"]', 'Sprint Review', 'Sprint Reviews inspect the increment delivered during the sprint with project stakeholders.'),
(3, 3, 'Scrum Ceremonies', 'conceptual', 'multiple_choice', 'Which Scrum event is dedicated to internal team reflection on process improvement and identifying what went well or needs improvement?', NULL, '["Sprint Retrospective", "Sprint Review", "Sprint Planning", "Product Demo"]', 'Sprint Retrospective', 'The Retrospective allows the Scrum team to inspect its own performance and plan process improvements.'),
(3, 3, 'DSDM Framework', 'conceptual', 'multiple_choice', 'What is the primary requirement prioritization technique utilized within Dynamic Systems Development Method (DSDM)?', NULL, '["MoSCoW (Must have, Should have, Could have, Won''t have)", "Gantt analysis", "PERT estimation", "KISS evaluation"]', 'MoSCoW (Must have, Should have, Could have, Won''t have)', 'DSDM heavily utilizes MoSCoW prioritization to manage delivery within fixed timeboxes.'),
(3, 3, 'DSDM Techniques', 'conceptual', 'multiple_choice', 'How does timeboxing operate within DSDM when project resources and schedules are fixed?', NULL, '["Requirements with the lowest priority are omitted if time runs out", "The budget is automatically increased", "The delivery deadline is extended indefinitely", "All testing phases are skipped"]', 'Requirements with the lowest priority are omitted if time runs out', 'Fixed timeboxes in DSDM adjust product scope by dropping low-priority features when constraints are reached.'),
(3, 3, 'Feature Driven Development', 'conceptual', 'multiple_choice', 'Feature Driven Development (FDD) organizes software progress around:', NULL, '["Short, specific phases of work designed and built per feature", "Exhaustive upfront architectural documentation", "Purely ad-hoc daily coding tasks", "Annual system release cycles"]', 'Short, specific phases of work designed and built per feature', 'FDD structures development into short, discrete iterations organized specifically around feature sets.'),
(3, 3, 'Lean Software Development', 'conceptual', 'multiple_choice', 'Lean Software Development is derived from principles originating in which domain?', NULL, '["Lean Manufacturing and the Toyota Production System", "Civil construction blueprints", "Aerospace defense contracting", "Academic research libraries"]', 'Lean Manufacturing and the Toyota Production System', 'Lean software engineering adapts lean manufacturing principles from Toyota to minimize waste and accelerate value.'),
(3, 3, 'Lean Principles', 'conceptual', 'multiple_choice', 'Which of the following is one of the seven primary principles of Lean Software Development?', NULL, '["Eliminate Waste", "Maximize Documentation", "Lock Requirements Early", "Centralize Decision-Making"]', 'Eliminate Waste', 'Lean software development mandates the elimination of non-value-adding waste (such as partially done work or unnecessary features).'),
(3, 3, 'Extreme Programming', 'conceptual', 'multiple_choice', 'Extreme Programming (XP) is particularly suitable for software projects characterized by:', NULL, '["Constantly changing user demands and unstable requirements", "Fixed requirements that never alter", "Large teams of over 500 developers", "Projects with zero customer involvement"]', 'Constantly changing user demands and unstable requirements', 'XP thrives in environments with volatile or rapidly evolving customer requirements.'),
(3, 3, 'Extreme Programming Practices', 'conceptual', 'multiple_choice', 'Which practice is heavily integrated into the execution phase of Extreme Programming?', NULL, '["Pair programming and automated unit testing", "Single-developer isolation", "Infrequent releases every two years", "Eliminating all unit testing"]', 'Pair programming and automated unit testing', 'XP emphasizes continuous feedback through practices such as automated unit testing and close collaboration.'),
(3, 3, 'Agile Methodology Selection', 'conceptual', 'multiple_choice', 'A software development agency is hired by a startup whose product concept is fluid and expected to undergo significant weekly changes based on early user feedback. The team needs a framework that mandates automated unit testing, short release cycles, and active continuous customer input. Which methodology best aligns with these needs?', NULL, '["Extreme Programming (XP)", "Waterfall Model", "Traditional SDLC", "Structured System Analysis"]', 'Extreme Programming (XP)', 'XP excels when customer requirements change frequently and relies on automated unit testing, continuous customer involvement, and rapid iterations.'),
(3, 3, 'Scrum Ceremonies Application', 'conceptual', 'multiple_choice', 'At the end of a two-week sprint, a Scrum team meets to evaluate why several user stories were blocked by database configuration delays and agrees to implement automated deployment scripts in the upcoming sprint. Which Scrum event is taking place?', NULL, '["Sprint Retrospective", "Sprint Review", "Daily Scrum", "Backlog Refinement"]', 'Sprint Retrospective', 'The Sprint Retrospective focuses on evaluating internal team processes, tools, and relationships to plan improvements for the next sprint.'),
(3, 3, 'Agile Methodologies', 'conceptual', 'multiple_choice', 'Which statement best describes Agile software development?', NULL, '["Development follows a fixed sequence with no changes", "Requirements and solutions evolve through collaboration", "Documentation must be completed before development begins", "Customers participate only after the product is completed"]', 'Requirements and solutions evolve through collaboration', 'Agile software development comprises approaches under which requirements and solutions evolve through collaborative effort.'),
(3, 3, 'Agile Values', 'conceptual', 'multiple_choice', 'Which of the following is one of the Agile Development Values?', NULL, '["Processes and tools over individuals and interactions", "Contract negotiation over customer collaboration", "Working software over comprehensive documentation", "Following a plan over responding to change"]', 'Working software over comprehensive documentation', 'Agile development values Working Software over comprehensive documentation.'),
(3, 3, 'Agile Principles', 'conceptual', 'multiple_choice', 'According to Agile principles, what is the primary measure of progress?', NULL, '["Completed documentation", "Working software", "Number of meetings", "Project budget"]', 'Working software', 'Working software is the primary measure of progress in Agile development.'),
(3, 3, 'Agile vs Waterfall', 'conceptual', 'multiple_choice', 'Which characteristic distinguishes Agile from the Waterfall model?', NULL, '["Agile follows only one development phase.", "Agile discourages customer involvement.", "Agile uses an incremental and iterative approach.", "Agile requires all requirements to remain unchanged."]', 'Agile uses an incremental and iterative approach.', 'The Agile method proposes an incremental and iterative approach to software design, unlike Waterfall which flows sequentially.'),
(3, 3, 'Agile Principles', 'conceptual', 'multiple_choice', 'Agile encourages teams to respond to changing requirements:', NULL, '["Only before development starts", "Only during planning", "Even late in development", "Never after requirements are approved"]', 'Even late in development', 'Agile principles welcome changing requirements, even in late development.'),
(3, 3, 'Crystal Methodology', 'conceptual', 'multiple_choice', 'Which Agile methodology focuses primarily on people and their interactions rather than processes and tools?', NULL, '["DSDM", "Crystal Methodology", "FDD", "Waterfall"]', 'Crystal Methodology', 'Crystal method is an agile software development approach that focuses primarily on people and their interactions rather than on processes and tools.'),
(3, 3, 'Crystal Methodology', 'conceptual', 'multiple_choice', 'Who developed the Crystal Methodology?', NULL, '["Kent Beck", "Alistair Cockburn", "Ken Schwaber", "Mary Poppendieck"]', 'Alistair Cockburn', 'Crystal Methodology was developed by Alistair Cockburn.'),
(3, 3, 'Crystal Methodology', 'conceptual', 'multiple_choice', 'Which sequence correctly represents the three phases of Crystal Methodology?', NULL, '["Planning, Coding, Testing", "Analysis, Design, Deployment", "Chartering, Cyclic Delivery, Wrap Up", "Feasibility, Development, Maintenance"]', 'Chartering, Cyclic Delivery, Wrap Up', 'The three phases of Crystal Methodology are Chartering, Cyclic Delivery, and Wrap Up.'),
(3, 3, 'Agile Values', 'conceptual', 'multiple_choice', 'Agile emphasizes individuals and interactions over processes and tools.', NULL, '["True", "False"]', 'True', 'Individuals and interactions over processes and tools is one of the core Agile Development Values.'),
(3, 3, 'Agile Values', 'conceptual', 'multiple_choice', 'Agile considers comprehensive documentation more important than working software.', NULL, '["True", "False"]', 'False', 'Agile values Working Software over comprehensive documentation.'),

-- MODULE 4
(3, 4, 'Functional Model Symbols', 'conceptual', 'multiple_choice', 'In functional model notation (DFD), what does a circle or rounded rectangle signify?', NULL, '["A Process that transforms inputs into outputs", "An External Entity", "A Data Store", "A Flow line"]', 'A Process that transforms inputs into outputs', 'Processes accept incoming data flows, perform transformations, and emit outgoing data flows.'),
(3, 4, 'Data Flow Diagram Symbols', 'conceptual', 'multiple_choice', 'In a Data Flow Diagram (DFD), how is an External Entity represented?', NULL, '["By a rectangle denoting an external person, system, or organization interacting with the system", "By an open rectangle", "By a rounded circle", "By a dashed line"]', 'By a rectangle denoting an external person, system, or organization interacting with the system', 'Rectangles in DFDs represent external entities that originate or receive data flows.'),
(3, 4, 'Data Flow Diagram Symbols', 'conceptual', 'multiple_choice', 'In DFD notation, an open rectangle (or open-ended rectangle) represents a:', NULL, '["Data Store", "Process", "External Entity", "Decision Gate"]', 'Data Store', 'Data stores—where data resides at rest permanently or temporarily—are symbolized by open rectangles.'),
(3, 4, 'Data Flow Diagram Hierarchy', 'conceptual', 'multiple_choice', 'What is a DFD Level 0 diagram (also known as a Context Diagram)?', NULL, '["An overarching diagram showing the entire system as a single process interacting with external entities", "A granular diagram showing line-by-line code logic", "A detailed database schema diagram", "A hardware wiring blueprint"]', 'An overarching diagram showing the entire system as a single process interacting with external entities', 'DFD Level 0 abstracts the entire system into a single core process linked to surrounding external entities.'),
(3, 4, 'System Requirements Overview', 'conceptual', 'multiple_choice', 'Software products typically define two tiers of system requirements known as:', NULL, '["Minimum and Recommended requirements", "Basic and Advanced options", "Hardware and Software licenses", "Internal and External parameters"]', 'Minimum and Recommended requirements', 'System specifications outline minimum hardware/software thresholds needed to run, and recommended specs for optimal performance.'),
(3, 4, 'Fact Finding Techniques', 'conceptual', 'multiple_choice', 'Which fact-finding technique is qualitative and allows users to express opinions and experiences in their own words?', NULL, '["Open-ended Questionnaires / Interviews", "Closed-ended Questionnaires", "Automated log auditing", "SQL query tracing"]', 'Open-ended Questionnaires / Interviews', 'Open-ended questionnaires and interviews capture qualitative user sentiment, narrative experiences, and problem feedback.'),
(3, 4, 'Fact Finding Techniques', 'conceptual', 'multiple_choice', 'Which fact-finding method requires analysts to inspect basic business documents, bills, policy manuals, and standard operating procedures?', NULL, '["Record inspections or reviews", "Direct observation", "Prototyping", "A/B testing"]', 'Record inspections or reviews', 'Record inspection reviews legacy documentation, operational logs, and policy manuals to analyze current workflows.'),
(3, 4, 'DFD Architecture Analysis', 'conceptual', 'multiple_choice', 'A systems analyst is modeling a hospital management system. She draws a top-level diagram containing a single central process labeled "Hospital Information System" connected to "Patient", "Doctor", and "Insurance Provider". Which type of diagram has she created?', NULL, '["Context Diagram (DFD Level 0)", "Functional Flow Block Diagram Level 2", "Physical Data Model", "Use Case Activity Grid"]', 'Context Diagram (DFD Level 0)', 'A DFD Level 0 (Context Diagram) represents the entire system as one central process surrounded by external entities.'),
(3, 4, 'Requirements Analysis Techniques', 'conceptual', 'multiple_choice', 'An engineering team needs to gather system preferences from 5,000 distributed employees across multiple regional offices within a strict two-day window. Which fact-finding technique is most appropriate and efficient for generating quantifiable data?', NULL, '["Closed-ended Questionnaires", "Individual face-to-face interviews", "Direct continuous observation of all employees", "Record inspection of historical paper logs"]', 'Closed-ended Questionnaires', 'Closed-ended questionnaires allow rapid, cost-effective data collection from large, geographically distributed populations while yielding structured quantitative data.'),
(3, 4, 'System Models', 'conceptual', 'multiple_choice', 'What is a model in systems development?', NULL, '["A complete copy of an existing system", "A simplified description of a system", "A collection of programming codes", "A list of hardware components"]', 'A simplified description of a system', 'A model is a description where details are removed in a systematic manner and simplified in an understanding way.'),
(3, 4, 'System Models', 'conceptual', 'multiple_choice', 'What does systems modeling use to conceptualize and construct systems?', NULL, '["Models and diagrams", "Programming languages only", "Financial statements", "Marketing plans"]', 'Models and diagrams', 'Systems modeling is the study of the use of models or diagrams to conceptualize and construct systems.'),
(3, 4, 'Functional Modeling', 'conceptual', 'multiple_choice', 'Which modeling approach represents the functions, activities, and operations within a system?', NULL, '["Enterprise modeling", "Data modeling", "Functional modeling", "Financial modeling"]', 'Functional modeling', 'Functional modeling is a structured representation of the functions, activities, actions, processes, and operations within the modeled system.'),
(3, 4, 'Functional Modeling', 'conceptual', 'multiple_choice', 'In functional modeling, which element illustrates the transformation of input into output?', NULL, '["Process", "Data store", "External entity", "Flow line"]', 'Process', 'Process illustrates the transformation from input to output.'),
(3, 4, 'Functional Flow Block Diagram', 'conceptual', 'multiple_choice', 'What does a Functional Flow Block Diagram primarily present?', NULL, '["Database table relationships", "Time-sequenced functional activities", "Hardware prices", "Employee records"]', 'Time-sequenced functional activities', 'Functional flow block diagrams (FFBD) present multi-tier, time-sequenced, step-by-step flows of system functions.'),
(3, 4, 'Business Process Modeling', 'conceptual', 'multiple_choice', 'What is the primary purpose of Business Process Modeling?', NULL, '["To identify computer specifications", "To represent, analyze, and improve organizational processes", "To determine employee salaries", "To install software applications"]', 'To represent, analyze, and improve organizational processes', 'Business process modeling is the activity of representing processes of an enterprise, so that current processes may be analyzed, improved, and automated.'),
(3, 4, 'Business Process Modeling', 'conceptual', 'multiple_choice', 'Which type of business process creates the organization''s primary value stream?', NULL, '["Management process", "Supporting process", "Operational process", "Documentation process"]', 'Operational process', 'Operational processes constitute the core business and create the primary value stream.'),
(3, 4, 'Business Process Modeling', 'conceptual', 'multiple_choice', 'Which of the following is an example of a supporting process?', NULL, '["Strategic management", "Product manufacturing", "Marketing and sales", "Recruitment and technical support"]', 'Recruitment and technical support', 'Supporting processes support core processes, such as accounting, recruitment, and technical support.'),
(3, 4, 'Business Process Modeling', 'conceptual', 'multiple_choice', 'What is the purpose of Business Process Model and Notation (BPMN)?', NULL, '["To provide a graphical notation for business processes", "To identify computer hardware", "To calculate software costs", "To create database records"]', 'To provide a graphical notation for business processes', 'BPMN provides a graphical notation for specifying business processes in a Business Process Diagram.');